/**
 * Test reconfiguring a Reconfigurable.
 */
@Test
public void testReconfigure() {
    ReconfigurableDummy dummy = new ReconfigurableDummy(conf1);
    assertTrue(PROP1 + " set to wrong value ", dummy.getConf().get(PROP1).equals(VAL1));
    assertTrue(PROP2 + " set to wrong value ", dummy.getConf().get(PROP2).equals(VAL1));
    assertTrue(PROP3 + " set to wrong value ", dummy.getConf().get(PROP3).equals(VAL1));
    assertTrue(PROP4 + " set to wrong value ", dummy.getConf().get(PROP4) == null);
    assertTrue(PROP5 + " set to wrong value ", dummy.getConf().get(PROP5) == null);
    assertTrue(PROP1 + " should be reconfigurable ", dummy.isPropertyReconfigurable(PROP1));
    assertTrue(PROP2 + " should be reconfigurable ", dummy.isPropertyReconfigurable(PROP2));
    assertFalse(PROP3 + " should not be reconfigurable ", dummy.isPropertyReconfigurable(PROP3));
    assertTrue(PROP4 + " should be reconfigurable ", dummy.isPropertyReconfigurable(PROP4));
    assertFalse(PROP5 + " should not be reconfigurable ", dummy.isPropertyReconfigurable(PROP5));
    // change something to the same value as before
    {
        boolean exceptionCaught = false;
        try {
            dummy.reconfigureProperty(PROP1, VAL1);
            assertTrue(PROP1 + " set to wrong value ", dummy.getConf().get(PROP1).equals(VAL1));
        } catch (ReconfigurationException e) {
            exceptionCaught = true;
        }
        assertFalse("received unexpected exception", exceptionCaught);
    }
    // change something to null
    {
        boolean exceptionCaught = false;
        try {
            dummy.reconfigureProperty(PROP1, null);
            assertTrue(PROP1 + "set to wrong value ", dummy.getConf().get(PROP1) == null);
        } catch (ReconfigurationException e) {
            exceptionCaught = true;
        }
        assertFalse("received unexpected exception", exceptionCaught);
    }
    // change something to a different value than before
    {
        boolean exceptionCaught = false;
        try {
            dummy.reconfigureProperty(PROP1, VAL2);
            assertTrue(PROP1 + "set to wrong value ", dummy.getConf().get(PROP1).equals(VAL2));
        } catch (ReconfigurationException e) {
            exceptionCaught = true;
        }
        assertFalse("received unexpected exception", exceptionCaught);
    }
    // set unset property to null
    {
        boolean exceptionCaught = false;
        try {
            dummy.reconfigureProperty(PROP4, null);
            assertTrue(PROP4 + "set to wrong value ", dummy.getConf().get(PROP4) == null);
        } catch (ReconfigurationException e) {
            exceptionCaught = true;
        }
        assertFalse("received unexpected exception", exceptionCaught);
    }
    // set unset property
    {
        boolean exceptionCaught = false;
        try {
            dummy.reconfigureProperty(PROP4, VAL1);
            assertTrue(PROP4 + "set to wrong value ", dummy.getConf().get(PROP4).equals(VAL1));
        } catch (ReconfigurationException e) {
            exceptionCaught = true;
        }
        assertFalse("received unexpected exception", exceptionCaught);
    }
    // try to set unset property to null (not reconfigurable)
    {
        boolean exceptionCaught = false;
        try {
            dummy.reconfigureProperty(PROP5, null);
        } catch (ReconfigurationException e) {
            exceptionCaught = true;
        }
        assertTrue("did not receive expected exception", exceptionCaught);
    }
    // try to set unset property to value (not reconfigurable)
    {
        boolean exceptionCaught = false;
        try {
            dummy.reconfigureProperty(PROP5, VAL1);
        } catch (ReconfigurationException e) {
            exceptionCaught = true;
        }
        assertTrue("did not receive expected exception", exceptionCaught);
    }
    // try to change property to value (not reconfigurable)
    {
        boolean exceptionCaught = false;
        try {
            dummy.reconfigureProperty(PROP3, VAL2);
        } catch (ReconfigurationException e) {
            exceptionCaught = true;
        }
        assertTrue("did not receive expected exception", exceptionCaught);
    }
    // try to change property to null (not reconfigurable)
    {
        boolean exceptionCaught = false;
        try {
            dummy.reconfigureProperty(PROP3, null);
        } catch (ReconfigurationException e) {
            exceptionCaught = true;
        }
        assertTrue("did not receive expected exception", exceptionCaught);
    }
}

/**
 * Test whether configuration changes are visible in another thread.
 */
@Test
public void testThread() throws ReconfigurationException {
    ReconfigurableDummy dummy = new ReconfigurableDummy(conf1);
    assertTrue(dummy.getConf().get(PROP1).equals(VAL1));
    Thread dummyThread = new Thread(dummy);
    dummyThread.start();
    try {
        Thread.sleep(500);
    } catch (InterruptedException ignore) {
        // do nothing
    }
    dummy.reconfigureProperty(PROP1, VAL2);
    long endWait = Time.now() + 2000;
    while (dummyThread.isAlive() && Time.now() < endWait) {
        try {
            Thread.sleep(50);
        } catch (InterruptedException ignore) {
            // do nothing
        }
    }
    assertFalse("dummy thread should not be alive", dummyThread.isAlive());
    dummy.running = false;
    try {
        dummyThread.join();
    } catch (InterruptedException ignore) {
        // do nothing
    }
    assertTrue(PROP1 + " is set to wrong value", dummy.getConf().get(PROP1).equals(VAL2));
}

@Test
public void testAsyncReconfigure() throws ReconfigurationException, IOException, InterruptedException {
    AsyncReconfigurableDummy dummy = spy(new AsyncReconfigurableDummy(conf1));
    List<PropertyChange> changes = Lists.newArrayList();
    changes.add(new PropertyChange("name1", "new1", "old1"));
    changes.add(new PropertyChange("name2", "new2", "old2"));
    changes.add(new PropertyChange("name3", "new3", "old3"));
    doReturn(changes).when(dummy).getChangedProperties(any(Configuration.class), any(Configuration.class));
    doReturn(true).when(dummy).isPropertyReconfigurable(eq("name1"));
    doReturn(false).when(dummy).isPropertyReconfigurable(eq("name2"));
    doReturn(true).when(dummy).isPropertyReconfigurable(eq("name3"));
    doReturn("dummy").when(dummy).reconfigurePropertyImpl(eq("name1"), anyString());
    doReturn("dummy").when(dummy).reconfigurePropertyImpl(eq("name2"), anyString());
    doThrow(new ReconfigurationException("NAME3", "NEW3", "OLD3", new IOException("io exception"))).when(dummy).reconfigurePropertyImpl(eq("name3"), anyString());
    dummy.startReconfigurationTask();
    waitAsyncReconfigureTaskFinish(dummy);
    ReconfigurationTaskStatus status = dummy.getReconfigurationTaskStatus();
    assertEquals(2, status.getStatus().size());
    for (Map.Entry<PropertyChange, Optional<String>> result : status.getStatus().entrySet()) {
        PropertyChange change = result.getKey();
        if (change.prop.equals("name1")) {
            assertFalse(result.getValue().isPresent());
        } else if (change.prop.equals("name2")) {
            assertThat(result.getValue().get(), containsString("Property name2 is not reconfigurable"));
        } else if (change.prop.equals("name3")) {
            assertThat(result.getValue().get(), containsString("io exception"));
        } else {
            fail("Unknown property: " + change.prop);
        }
    }
}

@Test(timeout = 30000)
public void testStartReconfigurationFailureDueToExistingRunningTask() throws InterruptedException, IOException {
    AsyncReconfigurableDummy dummy = spy(new AsyncReconfigurableDummy(conf1));
    List<PropertyChange> changes = Lists.newArrayList(new PropertyChange(PROP1, "new1", "old1"));
    doReturn(changes).when(dummy).getChangedProperties(any(Configuration.class), any(Configuration.class));
    ReconfigurationTaskStatus status = dummy.getReconfigurationTaskStatus();
    assertFalse(status.hasTask());
    dummy.startReconfigurationTask();
    status = dummy.getReconfigurationTaskStatus();
    assertTrue(status.hasTask());
    assertFalse(status.stopped());
    // An active reconfiguration task is running.
    try {
        dummy.startReconfigurationTask();
        fail("Expect to throw IOException.");
    } catch (IOException e) {
        GenericTestUtils.assertExceptionContains("Another reconfiguration task is running", e);
    }
    status = dummy.getReconfigurationTaskStatus();
    assertTrue(status.hasTask());
    assertFalse(status.stopped());
    dummy.latch.countDown();
    waitAsyncReconfigureTaskFinish(dummy);
    status = dummy.getReconfigurationTaskStatus();
    assertTrue(status.hasTask());
    assertTrue(status.stopped());
    // The first task has finished.
    dummy.startReconfigurationTask();
    waitAsyncReconfigureTaskFinish(dummy);
    ReconfigurationTaskStatus status2 = dummy.getReconfigurationTaskStatus();
    assertTrue(status2.getStartTime() >= status.getEndTime());
    dummy.shutdownReconfigurationTask();
    try {
        dummy.startReconfigurationTask();
        fail("Expect to throw IOException");
    } catch (IOException e) {
        GenericTestUtils.assertExceptionContains("The server is stopped", e);
    }
}

