    Path file = new Path(TEST_ROOT_DIR, "test-append");
    fs.delete(file, true);
    FSDataOutputStream out = fs.create(file);
    try {
        out.write("text1".getBytes());
    } finally {
        out.close();
    }
    // Verify the position
    out = fs.append(file);
    try {
        assertEquals(5, out.getPos());
        out.write("text2".getBytes());
    } finally {
        out.close();
    }
    // Verify the content
    FSDataInputStream in = fs.open(file);
    try {
