    try {
        NativeIO.renameTo(nonExistentFile, targetFile);
        Assert.fail();
    } catch (NativeIOException e) {
        if (Path.WINDOWS) {
            Assert.assertEquals(String.format("The system cannot find the file specified.%n"), e.getMessage());
