public void testAckQuorum() throws Exception {
    // slow bookie
    newBookie = bkutil.newBookie();
    // make quorum size and ensemble size same to avoid the interleave writing
    // of the ledger entries
    int ensembleSize = numBookies + 1;
    int quorumSize = numBookies + 1;
    int ackSize = numBookies;
    // ensure that the journal manager has to use all bookies,
    // so that a failure will fail the journal manager
    Configuration conf = new Configuration();
    conf.setInt(BookKeeperJournalManager.BKJM_BOOKKEEPER_ENSEMBLE_SIZE, ensembleSize);
    conf.setInt(BookKeeperJournalManager.BKJM_BOOKKEEPER_QUORUM_SIZE, quorumSize);
    conf.setInt(BookKeeperJournalManager.BKJM_BOOKKEEPER_ACK_QUORUM_SIZE, ackSize);
    // sets 60 minutes
    conf.setInt(BookKeeperJournalManager.BKJM_BOOKKEEPER_ADD_ENTRY_TIMEOUT_SEC, 3600);
    NamespaceInfo nsi = newNSInfo();
    BookKeeperJournalManager bkjm = new BookKeeperJournalManager(conf, BKJMUtil.createJournalURI("/hdfsjournal-onebookiefailure"), nsi);
    bkjm.format(nsi);
    CountDownLatch sleepLatch = new CountDownLatch(1);
    sleepBookie(sleepLatch, newBookie);
    EditLogOutputStream out = bkjm.startLogSegment(1, NameNodeLayoutVersion.CURRENT_LAYOUT_VERSION);
    int numTransactions = 100;
    for (long i = 1; i <= numTransactions; i++) {
        FSEditLogOp op = FSEditLogTestUtil.getNoOpInstance();
        op.setTransactionId(i);
        out.write(op);
    }
    out.close();
    bkjm.finalizeLogSegment(1, numTransactions);
    List<EditLogInputStream> in = new ArrayList<EditLogInputStream>();
    bkjm.selectInputStreams(in, 1, true);
    try {
        assertEquals(numTransactions, FSEditLogTestUtil.countTransactionsInStream(in.get(0)));
    } finally {
        sleepLatch.countDown();
        in.get(0).close();
        bkjm.close();
    }
}

/**
 * Test speculative read feature supported by bookkeeper. Keep one bookie
 * alive and sleep all the other bookies. Non spec client will hang for long
 * time to read the entries from the bookkeeper.
 */
@Test(timeout = 120000)
public void testSpeculativeRead() throws Exception {
    // starting 9 more servers
    for (int i = 1; i < 10; i++) {
        bks.add(bkutil.newBookie());
    }
    NamespaceInfo nsi = newNSInfo();
    Configuration conf = new Configuration();
    int ensembleSize = numLocalBookies + 9;
    conf.setInt(BookKeeperJournalManager.BKJM_BOOKKEEPER_ENSEMBLE_SIZE, ensembleSize);
    conf.setInt(BookKeeperJournalManager.BKJM_BOOKKEEPER_QUORUM_SIZE, ensembleSize);
    conf.setInt(BookKeeperJournalManager.BKJM_BOOKKEEPER_SPECULATIVE_READ_TIMEOUT_MS, 100);
    // sets 60 minute
    conf.setInt(BookKeeperJournalManager.BKJM_BOOKKEEPER_READ_ENTRY_TIMEOUT_SEC, 3600);
    BookKeeperJournalManager bkjm = new BookKeeperJournalManager(conf, BKJMUtil.createJournalURI("/hdfsjournal-specread"), nsi);
    bkjm.format(nsi);
    final long numTransactions = 1000;
    EditLogOutputStream out = bkjm.startLogSegment(1, NameNodeLayoutVersion.CURRENT_LAYOUT_VERSION);
    for (long i = 1; i <= numTransactions; i++) {
        FSEditLogOp op = FSEditLogTestUtil.getNoOpInstance();
        op.setTransactionId(i);
        out.write(op);
    }
    out.close();
    bkjm.finalizeLogSegment(1, numTransactions);
    List<EditLogInputStream> in = new ArrayList<EditLogInputStream>();
    bkjm.selectInputStreams(in, 1, true);
    // sleep 9 bk servers. Now only one server is running and responding to the
    // clients
    CountDownLatch sleepLatch = new CountDownLatch(1);
    for (final BookieServer bookie : bks) {
        sleepBookie(sleepLatch, bookie);
    }
    try {
        assertEquals(numTransactions, FSEditLogTestUtil.countTransactionsInStream(in.get(0)));
    } finally {
        in.get(0).close();
        sleepLatch.countDown();
        bkjm.close();
    }
}

/**
 * While boostrapping, in_progress transaction entries should be skipped.
 * Bootstrap usage for BKJM : "-force", "-nonInteractive", "-skipSharedEditsCheck"
 */
@Test
public void testBootstrapStandbyWithActiveNN() throws Exception {
    // make nn0 active
    cluster.transitionToActive(0);
    // do ops and generate in-progress edit log data
    Configuration confNN1 = cluster.getConfiguration(1);
    DistributedFileSystem dfs = (DistributedFileSystem) HATestUtil.configureFailoverFs(cluster, confNN1);
    for (int i = 1; i <= 10; i++) {
        dfs.mkdirs(new Path("/test" + i));
    }
    dfs.close();
    // shutdown nn1 and delete its edit log files
    cluster.shutdownNameNode(1);
    deleteEditLogIfExists(confNN1);
    cluster.getNameNodeRpc(0).setSafeMode(SafeModeAction.SAFEMODE_ENTER, true);
    cluster.getNameNodeRpc(0).saveNamespace(0, 0);
    cluster.getNameNodeRpc(0).setSafeMode(SafeModeAction.SAFEMODE_LEAVE, true);
    // check without -skipSharedEditsCheck, Bootstrap should fail for BKJM
    // immediately after saveNamespace
    int rc = BootstrapStandby.run(new String[] { "-force", "-nonInteractive" }, confNN1);
    Assert.assertEquals("Mismatches return code", 6, rc);
    // check with -skipSharedEditsCheck
    rc = BootstrapStandby.run(new String[] { "-force", "-nonInteractive", "-skipSharedEditsCheck" }, confNN1);
    Assert.assertEquals("Mismatches return code", 0, rc);
    // Checkpoint as fast as we can, in a tight loop.
    confNN1.setInt(DFSConfigKeys.DFS_NAMENODE_CHECKPOINT_PERIOD_KEY, 1);
    cluster.restartNameNode(1);
    cluster.transitionToStandby(1);
    NameNode nn0 = cluster.getNameNode(0);
    HATestUtil.waitForStandbyToCatchUp(nn0, cluster.getNameNode(1));
    long expectedCheckpointTxId = NameNodeAdapter.getNamesystem(nn0).getFSImage().getMostRecentCheckpointTxId();
    HATestUtil.waitForCheckpoint(cluster, 1, ImmutableList.of((int) expectedCheckpointTxId));
    // Should have copied over the namespace
    FSImageTestUtil.assertNNHasCheckpoints(cluster, 1, ImmutableList.of((int) expectedCheckpointTxId));
    FSImageTestUtil.assertNNFilesMatch(cluster);
}

