@Test
public void testPendingReconstruction() {
    PendingReconstructionBlocks pendingReconstructions;
    pendingReconstructions = new PendingReconstructionBlocks(TIMEOUT * 1000);
    pendingReconstructions.start();
    //
    // Add 10 blocks to pendingReconstruction.
    //
    DatanodeStorageInfo[] storages = DFSTestUtil.createDatanodeStorageInfos(10);
    for (int i = 0; i < storages.length; i++) {
        BlockInfo block = genBlockInfo(i, i, 0);
        DatanodeStorageInfo[] targets = new DatanodeStorageInfo[i];
        System.arraycopy(storages, 0, targets, 0, i);
        pendingReconstructions.increment(block, DatanodeStorageInfo.toDatanodeDescriptors(targets));
    }
    assertEquals("Size of pendingReconstruction ", 10, pendingReconstructions.size());
    //
    // remove one item
    //
    BlockInfo blk = genBlockInfo(8, 8, 0);
    // removes one replica
    pendingReconstructions.decrement(blk, storages[7].getDatanodeDescriptor());
    assertEquals("pendingReconstructions.getNumReplicas ", 7, pendingReconstructions.getNumReplicas(blk));
    //
    // insert the same item twice should be counted as once
    //
    pendingReconstructions.increment(blk, storages[0].getDatanodeDescriptor());
    assertEquals("pendingReconstructions.getNumReplicas ", 7, pendingReconstructions.getNumReplicas(blk));
    for (int i = 0; i < 7; i++) {
        // removes all replicas
        pendingReconstructions.decrement(blk, storages[i].getDatanodeDescriptor());
    }
    assertTrue(pendingReconstructions.size() == 9);
    pendingReconstructions.increment(blk, DatanodeStorageInfo.toDatanodeDescriptors(DFSTestUtil.createDatanodeStorageInfos(8)));
    assertTrue(pendingReconstructions.size() == 10);
    //
    // verify that the number of replicas returned
    // are sane.
    //
    for (int i = 0; i < 10; i++) {
        BlockInfo block = genBlockInfo(i, i, 0);
        int numReplicas = pendingReconstructions.getNumReplicas(block);
        assertTrue(numReplicas == i);
    }
    //
    // verify that nothing has timed out so far
    //
    assertTrue(pendingReconstructions.getTimedOutBlocks() == null);
    //
    // Wait for one second and then insert some more items.
    //
    try {
        Thread.sleep(1000);
    } catch (Exception e) {
    }
    for (int i = 10; i < 15; i++) {
        BlockInfo block = genBlockInfo(i, i, 0);
        pendingReconstructions.increment(block, DatanodeStorageInfo.toDatanodeDescriptors(DFSTestUtil.createDatanodeStorageInfos(i)));
    }
    assertTrue(pendingReconstructions.size() == 15);
    //
    // Wait for everything to timeout.
    //
    int loop = 0;
    while (pendingReconstructions.size() > 0) {
        try {
            Thread.sleep(1000);
        } catch (Exception e) {
        }
        loop++;
    }
    System.out.println("Had to wait for " + loop + " seconds for the lot to timeout");
    //
    // Verify that everything has timed out.
    //
    assertEquals("Size of pendingReconstructions ", 0, pendingReconstructions.size());
    Block[] timedOut = pendingReconstructions.getTimedOutBlocks();
    assertTrue(timedOut != null && timedOut.length == 15);
    for (int i = 0; i < timedOut.length; i++) {
        assertTrue(timedOut[i].getBlockId() < 15);
    }
    pendingReconstructions.stop();
}

/* Test that processpendingReconstructions will use the most recent
 * blockinfo from the blocksmap by placing a larger genstamp into
 * the blocksmap.
 */
@Test
public void testProcessPendingReconstructions() throws Exception {
    final Configuration conf = new HdfsConfiguration();
    conf.setLong(DFSConfigKeys.DFS_NAMENODE_RECONSTRUCTION_PENDING_TIMEOUT_SEC_KEY, TIMEOUT);
    MiniDFSCluster cluster = null;
    Block block;
    BlockInfo blockInfo;
    try {
        cluster = new MiniDFSCluster.Builder(conf).numDataNodes(DATANODE_COUNT).build();
        cluster.waitActive();
        FSNamesystem fsn = cluster.getNamesystem();
        BlockManager blkManager = fsn.getBlockManager();
        PendingReconstructionBlocks pendingReconstruction = blkManager.pendingReconstruction;
        LowRedundancyBlocks neededReconstruction = blkManager.neededReconstruction;
        BlocksMap blocksMap = blkManager.blocksMap;
        //
        // Add 1 block to pendingReconstructions with GenerationStamp = 0.
        //
        block = new Block(1, 1, 0);
        blockInfo = new BlockInfoContiguous(block, (short) 3);
        pendingReconstruction.increment(blockInfo, DatanodeStorageInfo.toDatanodeDescriptors(DFSTestUtil.createDatanodeStorageInfos(1)));
        BlockCollection bc = Mockito.mock(BlockCollection.class);
        // Place into blocksmap with GenerationStamp = 1
        blockInfo.setGenerationStamp(1);
        blocksMap.addBlockCollection(blockInfo, bc);
        assertEquals("Size of pendingReconstructions ", 1, pendingReconstruction.size());
        // Add a second block to pendingReconstructions that has no
        // corresponding entry in blocksmap
        block = new Block(2, 2, 0);
        blockInfo = new BlockInfoContiguous(block, (short) 3);
        pendingReconstruction.increment(blockInfo, DatanodeStorageInfo.toDatanodeDescriptors(DFSTestUtil.createDatanodeStorageInfos(1)));
        // verify 2 blocks in pendingReconstructions
        assertEquals("Size of pendingReconstructions ", 2, pendingReconstruction.size());
        //
        // Wait for everything to timeout.
        //
        while (pendingReconstruction.size() > 0) {
            try {
                Thread.sleep(100);
            } catch (Exception e) {
            }
        }
        //
        // Verify that block moves to neededReconstruction
        //
        while (neededReconstruction.size() == 0) {
            try {
                Thread.sleep(100);
            } catch (Exception e) {
            }
        }
        // Verify that the generation stamp we will try to replicate
        // is now 1
        for (Block b : neededReconstruction) {
            assertEquals("Generation stamp is 1 ", 1, b.getGenerationStamp());
        }
        // Verify size of neededReconstruction is exactly 1.
        assertEquals("size of neededReconstruction is 1 ", 1, neededReconstruction.size());
    } finally {
        if (cluster != null) {
            cluster.shutdown();
        }
    }
}

/**
 * Test if DatanodeProtocol#blockReceivedAndDeleted can correctly update the
 * pending reconstruction. Also make sure the blockReceivedAndDeleted call is
 * idempotent to the pending reconstruction.
 */
@Test
public void testBlockReceived() throws Exception {
    final Configuration conf = new HdfsConfiguration();
    conf.setLong(DFSConfigKeys.DFS_BLOCK_SIZE_KEY, 1024);
    MiniDFSCluster cluster = null;
    try {
        cluster = new MiniDFSCluster.Builder(conf).numDataNodes(DATANODE_COUNT).build();
        cluster.waitActive();
        DistributedFileSystem hdfs = cluster.getFileSystem();
        FSNamesystem fsn = cluster.getNamesystem();
        BlockManager blkManager = fsn.getBlockManager();
        final String file = "/tmp.txt";
        final Path filePath = new Path(file);
        short replFactor = 1;
        DFSTestUtil.createFile(hdfs, filePath, 1024L, replFactor, 0);
        // temporarily stop the heartbeat
        ArrayList<DataNode> datanodes = cluster.getDataNodes();
        for (int i = 0; i < DATANODE_COUNT; i++) {
            DataNodeTestUtils.setHeartbeatsDisabledForTests(datanodes.get(i), true);
        }
        hdfs.setReplication(filePath, (short) DATANODE_COUNT);
        BlockManagerTestUtil.computeAllPendingWork(blkManager);
        assertEquals(1, blkManager.pendingReconstruction.size());
        INodeFile fileNode = fsn.getFSDirectory().getINode4Write(file).asFile();
        BlockInfo[] blocks = fileNode.getBlocks();
        assertEquals(DATANODE_COUNT - 1, blkManager.pendingReconstruction.getNumReplicas(blocks[0]));
        LocatedBlock locatedBlock = hdfs.getClient().getLocatedBlocks(file, 0).get(0);
        DatanodeInfo existingDn = (locatedBlock.getLocations())[0];
        int reportDnNum = 0;
        String poolId = cluster.getNamesystem().getBlockPoolId();
        // let two datanodes (other than the one that already has the data) to
        // report to NN
        for (int i = 0; i < DATANODE_COUNT && reportDnNum < 2; i++) {
            if (!datanodes.get(i).getDatanodeId().equals(existingDn)) {
                DatanodeRegistration dnR = datanodes.get(i).getDNRegistrationForBP(poolId);
                StorageReceivedDeletedBlocks[] report = { new StorageReceivedDeletedBlocks("Fake-storage-ID-Ignored", new ReceivedDeletedBlockInfo[] { new ReceivedDeletedBlockInfo(blocks[0], BlockStatus.RECEIVED_BLOCK, "") }) };
                cluster.getNameNodeRpc().blockReceivedAndDeleted(dnR, poolId, report);
                reportDnNum++;
            }
        }
        // IBRs are async, make sure the NN processes all of them.
        cluster.getNamesystem().getBlockManager().flushBlockOps();
        assertEquals(DATANODE_COUNT - 3, blkManager.pendingReconstruction.getNumReplicas(blocks[0]));
        // let the same datanodes report again
        for (int i = 0; i < DATANODE_COUNT && reportDnNum < 2; i++) {
            if (!datanodes.get(i).getDatanodeId().equals(existingDn)) {
                DatanodeRegistration dnR = datanodes.get(i).getDNRegistrationForBP(poolId);
                StorageReceivedDeletedBlocks[] report = { new StorageReceivedDeletedBlocks("Fake-storage-ID-Ignored", new ReceivedDeletedBlockInfo[] { new ReceivedDeletedBlockInfo(blocks[0], BlockStatus.RECEIVED_BLOCK, "") }) };
                cluster.getNameNodeRpc().blockReceivedAndDeleted(dnR, poolId, report);
                reportDnNum++;
            }
        }
        cluster.getNamesystem().getBlockManager().flushBlockOps();
        assertEquals(DATANODE_COUNT - 3, blkManager.pendingReconstruction.getNumReplicas(blocks[0]));
        // re-enable heartbeat for the datanode that has data
        for (int i = 0; i < DATANODE_COUNT; i++) {
            DataNodeTestUtils.setHeartbeatsDisabledForTests(datanodes.get(i), false);
            DataNodeTestUtils.triggerHeartbeat(datanodes.get(i));
        }
        Thread.sleep(5000);
        assertEquals(0, blkManager.pendingReconstruction.size());
    } finally {
        if (cluster != null) {
            cluster.shutdown();
        }
    }
}

/**
 * Test if BlockManager can correctly remove corresponding pending records
 * when a file is deleted
 *
 * @throws Exception
 */
@Test
public void testPendingAndInvalidate() throws Exception {
    final Configuration CONF = new HdfsConfiguration();
    CONF.setLong(DFSConfigKeys.DFS_BLOCK_SIZE_KEY, 1024);
    CONF.setLong(DFSConfigKeys.DFS_HEARTBEAT_INTERVAL_KEY, DFS_REPLICATION_INTERVAL);
    CONF.setInt(DFSConfigKeys.DFS_NAMENODE_REPLICATION_INTERVAL_KEY, DFS_REPLICATION_INTERVAL);
    MiniDFSCluster cluster = new MiniDFSCluster.Builder(CONF).numDataNodes(DATANODE_COUNT).build();
    cluster.waitActive();
    FSNamesystem namesystem = cluster.getNamesystem();
    BlockManager bm = namesystem.getBlockManager();
    DistributedFileSystem fs = cluster.getFileSystem();
    try {
        // 1. create a file
        Path filePath = new Path("/tmp.txt");
        DFSTestUtil.createFile(fs, filePath, 1024, (short) 3, 0L);
        // 2. disable the heartbeats
        for (DataNode dn : cluster.getDataNodes()) {
            DataNodeTestUtils.setHeartbeatsDisabledForTests(dn, true);
        }
        // 3. mark a couple of blocks as corrupt
        LocatedBlock block = NameNodeAdapter.getBlockLocations(cluster.getNameNode(), filePath.toString(), 0, 1).get(0);
        cluster.getNamesystem().writeLock();
        try {
            bm.findAndMarkBlockAsCorrupt(block.getBlock(), block.getLocations()[0], "STORAGE_ID", "TEST");
            bm.findAndMarkBlockAsCorrupt(block.getBlock(), block.getLocations()[1], "STORAGE_ID", "TEST");
        } finally {
            cluster.getNamesystem().writeUnlock();
        }
        BlockManagerTestUtil.computeAllPendingWork(bm);
        BlockManagerTestUtil.updateState(bm);
        assertEquals(bm.getPendingReconstructionBlocksCount(), 1L);
        BlockInfo storedBlock = bm.getStoredBlock(block.getBlock().getLocalBlock());
        assertEquals(bm.pendingReconstruction.getNumReplicas(storedBlock), 2);
        // 4. delete the file
        fs.delete(filePath, true);
        // retry at most 10 times, each time sleep for 1s. Note that 10s is much
        // less than the default pending record timeout (5~10min)
        int retries = 10;
        long pendingNum = bm.getPendingReconstructionBlocksCount();
        while (pendingNum != 0 && retries-- > 0) {
            // let NN do the deletion
            Thread.sleep(1000);
            BlockManagerTestUtil.updateState(bm);
            pendingNum = bm.getPendingReconstructionBlocksCount();
        }
        assertEquals(pendingNum, 0L);
    } finally {
        cluster.shutdown();
    }
}

/**
 * Test when a block's replica is removed from RBW folder in one of the
 * datanode, namenode should ask to invalidate that corrupted block and
 * schedule replication for one more replica for that under replicated block.
 */
@Test(timeout = 600000)
public void testBlockInvalidationWhenRBWReplicaMissedInDN() throws IOException, InterruptedException {
    // This test cannot pass on Windows due to file locking enforcement.  It will
    // reject the attempt to delete the block file from the RBW folder.
    assumeTrue(!Path.WINDOWS);
    Configuration conf = new HdfsConfiguration();
    conf.setInt(DFSConfigKeys.DFS_REPLICATION_KEY, 2);
    conf.setLong(DFSConfigKeys.DFS_BLOCKREPORT_INTERVAL_MSEC_KEY, 300);
    conf.setLong(DFSConfigKeys.DFS_DATANODE_DIRECTORYSCAN_INTERVAL_KEY, 1);
    conf.setLong(DFSConfigKeys.DFS_HEARTBEAT_INTERVAL_KEY, 1);
    MiniDFSCluster cluster = new MiniDFSCluster.Builder(conf).numDataNodes(2).build();
    FSDataOutputStream out = null;
    try {
        final FSNamesystem namesystem = cluster.getNamesystem();
        FileSystem fs = cluster.getFileSystem();
        Path testPath = new Path("/tmp/TestRBWBlockInvalidation", "foo1");
        out = fs.create(testPath, (short) 2);
        out.writeBytes("HDFS-3157: " + testPath);
        out.hsync();
        cluster.startDataNodes(conf, 1, true, null, null, null);
        ExtendedBlock blk = DFSTestUtil.getFirstBlock(fs, testPath);
        // Delete partial block and its meta information from the RBW folder
        // of first datanode.
        MaterializedReplica replica = cluster.getMaterializedReplica(0, blk);
        replica.deleteData();
        replica.deleteMeta();
        out.close();
        int liveReplicas = 0;
        while (true) {
            if ((liveReplicas = countReplicas(namesystem, blk).liveReplicas()) < 2) {
                // This confirms we have a corrupt replica
                LOG.info("Live Replicas after corruption: " + liveReplicas);
                break;
            }
            Thread.sleep(100);
        }
        assertEquals("There should be less than 2 replicas in the " + "liveReplicasMap", 1, liveReplicas);
        while (true) {
            if ((liveReplicas = countReplicas(namesystem, blk).liveReplicas()) > 1) {
                //Wait till the live replica count becomes equal to Replication Factor
                LOG.info("Live Replicas after Rereplication: " + liveReplicas);
                break;
            }
            Thread.sleep(100);
        }
        assertEquals("There should be two live replicas", 2, liveReplicas);
        while (true) {
            Thread.sleep(100);
            if (countReplicas(namesystem, blk).corruptReplicas() == 0) {
                LOG.info("Corrupt Replicas becomes 0");
                break;
            }
        }
    } finally {
        if (out != null) {
            out.close();
        }
        cluster.shutdown();
    }
}

/**
 * Regression test for HDFS-4799, a case where, upon restart, if there
 * were RWR replicas with out-of-date genstamps, the NN could accidentally
 * delete good replicas instead of the bad replicas.
 */
@Test(timeout = 60000)
public void testRWRInvalidation() throws Exception {
    Configuration conf = new HdfsConfiguration();
    // Set the deletion policy to be randomized rather than the default.
    // The default is based on disk space, which isn't controllable
    // in the context of the test, whereas a random one is more accurate
    // to what is seen in real clusters (nodes have random amounts of free
    // space)
    conf.setClass(DFSConfigKeys.DFS_BLOCK_REPLICATOR_CLASSNAME_KEY, RandomDeleterPolicy.class, BlockPlacementPolicy.class);
    // Speed up the test a bit with faster heartbeats.
    conf.setInt(DFSConfigKeys.DFS_HEARTBEAT_INTERVAL_KEY, 1);
    // Test with a bunch of separate files, since otherwise the test may
    // fail just due to "good luck", even if a bug is present.
    List<Path> testPaths = Lists.newArrayList();
    for (int i = 0; i < 10; i++) {
        testPaths.add(new Path("/test" + i));
    }
    MiniDFSCluster cluster = new MiniDFSCluster.Builder(conf).numDataNodes(2).build();
    try {
        List<FSDataOutputStream> streams = Lists.newArrayList();
        try {
            // Open the test files and write some data to each
            for (Path path : testPaths) {
                FSDataOutputStream out = cluster.getFileSystem().create(path, (short) 2);
                streams.add(out);
                out.writeBytes("old gs data\n");
                out.hflush();
            }
            // Shutdown one of the nodes in the pipeline
            DataNodeProperties oldGenstampNode = cluster.stopDataNode(0);
            // Write some more data and flush again. This data will only
            // be in the latter genstamp copy of the blocks.
            for (int i = 0; i < streams.size(); i++) {
                Path path = testPaths.get(i);
                FSDataOutputStream out = streams.get(i);
                out.writeBytes("new gs data\n");
                out.hflush();
                // Set replication so that only one node is necessary for this block,
                // and close it.
                cluster.getFileSystem().setReplication(path, (short) 1);
                out.close();
            }
            // Upon restart, there will be two replicas, one with an old genstamp
            // and one current copy. This test wants to ensure that the old genstamp
            // copy is the one that is deleted.
            LOG.info("=========================== restarting cluster");
            DataNodeProperties otherNode = cluster.stopDataNode(0);
            cluster.restartNameNode();
            // Restart the datanode with the corrupt replica first.
            cluster.restartDataNode(oldGenstampNode);
            cluster.waitActive();
            // Then the other node
            cluster.restartDataNode(otherNode);
            cluster.waitActive();
            // Compute and send invalidations, waiting until they're fully processed.
            cluster.getNameNode().getNamesystem().getBlockManager().computeInvalidateWork(2);
            cluster.triggerHeartbeats();
            HATestUtil.waitForDNDeletions(cluster);
            cluster.triggerDeletionReports();
            // Make sure we can still read the blocks.
            for (Path path : testPaths) {
                String ret = DFSTestUtil.readFile(cluster.getFileSystem(), path);
                assertEquals("old gs data\n" + "new gs data\n", ret);
            }
        } finally {
            IOUtils.cleanup(LOG, streams.toArray(new Closeable[0]));
        }
    } finally {
        cluster.shutdown();
    }
}

/**
 * When there are all the internal blocks available but they are not placed on
 * enough racks, NameNode should avoid normal decoding reconstruction but copy
 * an internal block to a new rack.
 *
 * In this test, we first need to create a scenario that a striped block has
 * all the internal blocks but distributed in <6 racks. Then we check if the
 * replication monitor can correctly schedule the reconstruction work for it.
 */
@Test
public void testReconstructForNotEnoughRacks() throws Exception {
    MiniDFSCluster.DataNodeProperties lastHost = stopDataNode(hosts[hosts.length - 1]);
    final Path file = new Path("/foo");
    // the file's block is in 9 dn but 5 racks
    DFSTestUtil.createFile(fs, file, BLOCK_STRIPED_CELL_SIZE * NUM_DATA_BLOCKS * 2, (short) 1, 0L);
    Assert.assertEquals(0, bm.numOfUnderReplicatedBlocks());
    final INodeFile fileNode = fsn.getFSDirectory().getINode4Write(file.toString()).asFile();
    BlockInfoStriped blockInfo = (BlockInfoStriped) fileNode.getLastBlock();
    // we now should have 9 internal blocks distributed in 5 racks
    Set<String> rackSet = new HashSet<>();
    for (DatanodeStorageInfo storage : blockInfo.storages) {
        rackSet.add(storage.getDatanodeDescriptor().getNetworkLocation());
    }
    Assert.assertEquals(NUM_DATA_BLOCKS - 1, rackSet.size());
    // restart the stopped datanode
    cluster.restartDataNode(lastHost);
    cluster.waitActive();
    // make sure we have 6 racks again
    NetworkTopology topology = bm.getDatanodeManager().getNetworkTopology();
    Assert.assertEquals(hosts.length, topology.getNumOfLeaves());
    Assert.assertEquals(NUM_DATA_BLOCKS, topology.getNumOfRacks());
    // pause all the heartbeats
    for (DataNode dn : cluster.getDataNodes()) {
        DataNodeTestUtils.setHeartbeatsDisabledForTests(dn, true);
    }
    fsn.writeLock();
    try {
        bm.processMisReplicatedBlocks();
    } finally {
        fsn.writeUnlock();
    }
    // check if replication monitor correctly schedule the replication work
    boolean scheduled = false;
    for (int i = 0; i < 5; i++) {
        // retry 5 times
        for (DatanodeStorageInfo storage : blockInfo.storages) {
            if (storage != null) {
                DatanodeDescriptor dn = storage.getDatanodeDescriptor();
                Assert.assertEquals(0, dn.getNumberOfBlocksToBeErasureCoded());
                if (dn.getNumberOfBlocksToBeReplicated() == 1) {
                    scheduled = true;
                }
            }
        }
        if (scheduled) {
            break;
        }
        Thread.sleep(1000);
    }
    Assert.assertTrue(scheduled);
}

