    client.reportBadBlocks(new LocatedBlock[] { new LocatedBlock(extendedBlock, new DatanodeInfo[] { readOnlyDataNode }) });
    // There should now be only 1 *location* for the block as the READ_ONLY_SHARED is corrupt
