@Test
public void testCircularLinkedListWrites() throws Exception {
    HAStressTestHarness harness = new HAStressTestHarness();
    // setup the harness
    harness.setNumberOfNameNodes(NUM_NAMENODES);
    harness.addFailoverThread(TIME_BETWEEN_FAILOVERS);
    harness.conf.setInt(HdfsClientConfigKeys.Failover.SLEEPTIME_MAX_KEY, 1000);
    harness.conf.setInt(HdfsClientConfigKeys.Failover.MAX_ATTEMPTS_KEY, 128);
    final MiniDFSCluster cluster = harness.startCluster();
    try {
        cluster.waitActive();
        cluster.transitionToActive(0);
        // setup the a circular writer
        FileSystem fs = harness.getFailoverFs();
        TestContext context = harness.testCtx;
        List<CircularWriter> writers = new ArrayList<CircularWriter>();
        for (int i = 0; i < NUM_THREADS; i++) {
            Path p = new Path("/test-" + i);
            fs.mkdirs(p);
            CircularWriter writer = new CircularWriter(context, LIST_LENGTH, fs, p);
            writers.add(writer);
            context.addThread(writer);
        }
        harness.startThreads();
        // wait for all the writer threads to finish, or that we exceed the time
        long start = System.currentTimeMillis();
        while ((System.currentTimeMillis() - start) < RUNTIME && writers.size() > 0) {
            for (int i = 0; i < writers.size(); i++) {
                CircularWriter writer = writers.get(i);
                // remove the writer from the ones to check
                if (writer.done.await(100, TimeUnit.MILLISECONDS)) {
                    writers.remove(i--);
                }
            }
        }
        assertEquals("Some writers didn't complete in expected runtime! Current writer state:" + writers, 0, writers.size());
        harness.stopThreads();
    } finally {
        System.err.println("===========================\n\n\n\n");
        harness.shutdown();
    }
}

@Test(timeout = 60000)
public void testInvalidateBlock() throws Exception {
    Configuration conf = new Configuration();
    HAUtil.setAllowStandbyReads(conf, true);
    conf.setInt(DFSConfigKeys.DFS_HA_TAILEDITS_PERIOD_KEY, 1);
    MiniDFSCluster cluster = new MiniDFSCluster.Builder(conf).nnTopology(MiniDFSNNTopology.simpleHATopology()).numDataNodes(3).build();
    try {
        cluster.waitActive();
        cluster.transitionToActive(0);
        NameNode nn1 = cluster.getNameNode(0);
        NameNode nn2 = cluster.getNameNode(1);
        FileSystem fs = HATestUtil.configureFailoverFs(cluster, conf);
        Thread.sleep(1000);
        LOG.info("==================================");
        DFSTestUtil.writeFile(fs, TEST_FILE_PATH, TEST_FILE_DATA);
        // Have to force an edit log roll so that the standby catches up
        nn1.getRpcServer().rollEditLog();
        LOG.info("==================================");
        // delete the file
        fs.delete(TEST_FILE_PATH, false);
        BlockManagerTestUtil.computeAllPendingWork(nn1.getNamesystem().getBlockManager());
        nn1.getRpcServer().rollEditLog();
        // standby nn doesn't need to invalidate blocks.
        assertEquals(0, nn2.getNamesystem().getBlockManager().getPendingDeletionBlocksCount());
        cluster.triggerHeartbeats();
        cluster.triggerBlockReports();
        // standby nn doesn't need to invalidate blocks.
        assertEquals(0, nn2.getNamesystem().getBlockManager().getPendingDeletionBlocksCount());
    } finally {
        cluster.shutdown();
    }
}

@Test(timeout = 300000)
public void testSBNCheckpoints() throws Exception {
    JournalSet standbyJournalSet = NameNodeAdapter.spyOnJournalSet(nns[1]);
    doEdits(0, 10);
    HATestUtil.waitForStandbyToCatchUp(nns[0], nns[1]);
    // Once the standby catches up, it should notice that it needs to
    // do a checkpoint and save one to its local directories.
    HATestUtil.waitForCheckpoint(cluster, 1, ImmutableList.of(12));
    GenericTestUtils.waitFor(new Supplier<Boolean>() {

        @Override
        public Boolean get() {
            if (tmpOivImgDir.list().length > 0) {
                return true;
            } else {
                return false;
            }
        }
    }, 1000, 60000);
    // It should have saved the oiv image too.
    assertEquals("One file is expected", 1, tmpOivImgDir.list().length);
    // It should also upload it back to the active.
    HATestUtil.waitForCheckpoint(cluster, 0, ImmutableList.of(12));
    // The standby should never try to purge edit logs on shared storage.
    Mockito.verify(standbyJournalSet, Mockito.never()).purgeLogsOlderThan(Mockito.anyLong());
}

/**
 * Test for the case when both of the NNs in the cluster are
 * in the standby state, and thus are both creating checkpoints
 * and uploading them to each other.
 * In this circumstance, they should receive the error from the
 * other node indicating that the other node already has a
 * checkpoint for the given txid, but this should not cause
 * an abort, etc.
 */
@Test(timeout = 300000)
public void testBothNodesInStandbyState() throws Exception {
    doEdits(0, 10);
    cluster.transitionToStandby(0);
    // Transitioning to standby closed the edit log on the active,
    // so the standby will catch up. Then, both will be in standby mode
    // with enough uncheckpointed txns to cause a checkpoint, and they
    // will each try to take a checkpoint and upload to each other.
    HATestUtil.waitForCheckpoint(cluster, 1, ImmutableList.of(12));
    HATestUtil.waitForCheckpoint(cluster, 0, ImmutableList.of(12));
    assertEquals(12, nns[0].getNamesystem().getFSImage().getMostRecentCheckpointTxId());
    assertEquals(12, nns[1].getNamesystem().getFSImage().getMostRecentCheckpointTxId());
    List<File> dirs = Lists.newArrayList();
    dirs.addAll(FSImageTestUtil.getNameNodeCurrentDirs(cluster, 0));
    dirs.addAll(FSImageTestUtil.getNameNodeCurrentDirs(cluster, 1));
    FSImageTestUtil.assertParallelFilesAreIdentical(dirs, ImmutableSet.<String>of());
}

/**
 * Test for the case when the SBN is configured to checkpoint based
 * on a time period, but no transactions are happening on the
 * active. Thus, it would want to save a second checkpoint at the
 * same txid, which is a no-op. This test makes sure this doesn't
 * cause any problem.
 */
@Test(timeout = 300000)
public void testCheckpointWhenNoNewTransactionsHappened() throws Exception {
    // Checkpoint as fast as we can, in a tight loop.
    cluster.getConfiguration(1).setInt(DFSConfigKeys.DFS_NAMENODE_CHECKPOINT_PERIOD_KEY, 0);
    cluster.restartNameNode(1);
    nns[1] = cluster.getNameNode(1);
    FSImage spyImage1 = NameNodeAdapter.spyOnFsImage(nns[1]);
    // We shouldn't save any checkpoints at txid=0
    Thread.sleep(1000);
    Mockito.verify(spyImage1, Mockito.never()).saveNamespace((FSNamesystem) Mockito.anyObject());
    // Roll the primary and wait for the standby to catch up
    HATestUtil.waitForStandbyToCatchUp(nns[0], nns[1]);
    Thread.sleep(2000);
    // We should make exactly one checkpoint at this new txid.
    Mockito.verify(spyImage1, Mockito.times(1)).saveNamespace((FSNamesystem) Mockito.anyObject(), Mockito.eq(NameNodeFile.IMAGE), (Canceler) Mockito.anyObject());
}

/**
 * Test cancellation of ongoing checkpoints when failover happens
 * mid-checkpoint.
 */
@Test(timeout = 120000)
public void testCheckpointCancellation() throws Exception {
    cluster.transitionToStandby(0);
    // Create an edit log in the shared edits dir with a lot
    // of mkdirs operations. This is solely so that the image is
    // large enough to take a non-trivial amount of time to load.
    // (only ~15MB)
    URI sharedUri = cluster.getSharedEditsDir(0, 1);
    File sharedDir = new File(sharedUri.getPath(), "current");
    File tmpDir = new File(MiniDFSCluster.getBaseDirectory(), "testCheckpointCancellation-tmp");
    FSNamesystem fsn = cluster.getNamesystem(0);
    FSImageTestUtil.createAbortedLogWithMkdirs(tmpDir, NUM_DIRS_IN_LOG, 3, fsn.getFSDirectory().getLastInodeId() + 1);
    String fname = NNStorage.getInProgressEditsFileName(3);
    new File(tmpDir, fname).renameTo(new File(sharedDir, fname));
    // Checkpoint as fast as we can, in a tight loop.
    cluster.getConfiguration(1).setInt(DFSConfigKeys.DFS_NAMENODE_CHECKPOINT_PERIOD_KEY, 0);
    cluster.restartNameNode(1);
    nns[1] = cluster.getNameNode(1);
    cluster.transitionToActive(0);
    boolean canceledOne = false;
    for (int i = 0; i < 10 && !canceledOne; i++) {
        doEdits(i * 10, i * 10 + 10);
        cluster.transitionToStandby(0);
        cluster.transitionToActive(1);
        cluster.transitionToStandby(1);
        cluster.transitionToActive(0);
        canceledOne = StandbyCheckpointer.getCanceledCount() > 0;
    }
    assertTrue(canceledOne);
}

/**
 * Test cancellation of ongoing checkpoints when failover happens
 * mid-checkpoint during image upload from standby to active NN.
 */
@Test(timeout = 60000)
public void testCheckpointCancellationDuringUpload() throws Exception {
    // Set dfs.namenode.checkpoint.txns differently on the first NN to avoid it
    // doing checkpoint when it becomes a standby
    cluster.getConfiguration(0).setInt(DFSConfigKeys.DFS_NAMENODE_CHECKPOINT_TXNS_KEY, 1000);
    // don't compress, we want a big image
    for (int i = 0; i < NUM_NNS; i++) {
        cluster.getConfiguration(i).setBoolean(DFSConfigKeys.DFS_IMAGE_COMPRESS_KEY, false);
    }
    // Throttle SBN upload to make it hang during upload to ANN
    for (int i = 1; i < NUM_NNS; i++) {
        cluster.getConfiguration(i).setLong(DFSConfigKeys.DFS_IMAGE_TRANSFER_RATE_KEY, 100);
    }
    for (int i = 0; i < NUM_NNS; i++) {
        cluster.restartNameNode(i);
    }
    // update references to each of the nns
    setNNs();
    cluster.transitionToActive(0);
    doEdits(0, 100);
    for (int i = 1; i < NUM_NNS; i++) {
        HATestUtil.waitForStandbyToCatchUp(nns[0], nns[i]);
        HATestUtil.waitForCheckpoint(cluster, i, ImmutableList.of(104));
    }
    cluster.transitionToStandby(0);
    cluster.transitionToActive(1);
    // Wait to make sure background TransferFsImageUpload thread was cancelled.
    // This needs to be done before the next test in the suite starts, so that a
    // file descriptor is not held open during the next cluster init.
    cluster.shutdown();
    cluster = null;
    GenericTestUtils.waitFor(new Supplier<Boolean>() {

        @Override
        public Boolean get() {
            ThreadMXBean threadBean = ManagementFactory.getThreadMXBean();
            ThreadInfo[] threads = threadBean.getThreadInfo(threadBean.getAllThreadIds(), 1);
            for (ThreadInfo thread : threads) {
                if (thread.getThreadName().startsWith("TransferFsImageUpload")) {
                    return false;
                }
            }
            return true;
        }
    }, 1000, 30000);
    // Assert that former active did not accept the canceled checkpoint file.
