        try {
            fs.getAclStatus(p);
        } catch (AccessControlException ignored) {
        }
        try {
            fs.setAcl(p, acls);
        } catch (AccessControlException ignored) {
        }
        try {
            fs.removeAcl(p);
        } catch (AccessControlException ignored) {
        }
        try {
            fs.removeDefaultAcl(p);
        } catch (AccessControlException ignored) {
        }
        try {
            fs.removeAclEntries(p, acls);
        } catch (AccessControlException ignored) {
        }
        try {
