@Test(timeout = 120000)
public void testXAttrSymlinks() throws Exception {
    fs.mkdirs(linkParent);
    fs.mkdirs(targetParent);
    DFSTestUtil.createFile(fs, target, 1024, (short) 3, 0xBEEFl);
    fs.createSymlink(target, link, false);
    fs.setXAttr(target, name1, value1);
    fs.setXAttr(target, name2, value2);
    Map<String, byte[]> xattrs = fs.getXAttrs(link);
    Assert.assertEquals(xattrs.size(), 2);
    Assert.assertArrayEquals(value1, xattrs.get(name1));
    Assert.assertArrayEquals(value2, xattrs.get(name2));
    fs.setXAttr(link, name3, null);
    xattrs = fs.getXAttrs(target);
    Assert.assertEquals(xattrs.size(), 3);
    Assert.assertArrayEquals(value1, xattrs.get(name1));
    Assert.assertArrayEquals(value2, xattrs.get(name2));
    Assert.assertArrayEquals(new byte[0], xattrs.get(name3));
    fs.removeXAttr(link, name1);
    xattrs = fs.getXAttrs(target);
    Assert.assertEquals(xattrs.size(), 2);
    Assert.assertArrayEquals(value2, xattrs.get(name2));
    Assert.assertArrayEquals(new byte[0], xattrs.get(name3));
    fs.removeXAttr(target, name3);
    xattrs = fs.getXAttrs(link);
    Assert.assertEquals(xattrs.size(), 1);
    Assert.assertArrayEquals(value2, xattrs.get(name2));
    fs.delete(linkParent, true);
    fs.delete(targetParent, true);
}

@Test(timeout = 60000)
public void testNestedEncryptionZones() throws Exception {
    verifyEncryption();
    // Restart NameNode to test if nested EZs can be loaded from edit logs
    cluster.restartNameNodes();
    cluster.waitActive();
    verifyEncryption();
    // Checkpoint and restart NameNode, to test if nested EZs can be loaded
    // from fsimage
    fs.setSafeMode(HdfsConstants.SafeModeAction.SAFEMODE_ENTER);
    fs.saveNamespace();
    fs.setSafeMode(HdfsConstants.SafeModeAction.SAFEMODE_LEAVE);
    cluster.restartNameNodes();
    cluster.waitActive();
    verifyEncryption();
    Path renamedTopEZFile = new Path(topEZDir, "renamedFile");
    Path renamedNestedEZFile = new Path(nestedEZDir, "renamedFile");
    try {
        fs.rename(topEZFile, renamedTopEZFile);
        fs.rename(nestedEZFile, renamedNestedEZFile);
    } catch (Exception e) {
        fail("Should be able to rename files within the same EZ.");
    }
    topEZFile = renamedTopEZFile;
    nestedEZFile = renamedNestedEZFile;
    topEZRawFile = new Path(rawDir, "topEZ/renamedFile");
    nestedEZRawFile = new Path(rawDir, "topEZ/nestedEZ/renamedFile");
    verifyEncryption();
    // Verify that files in top EZ cannot be moved into the nested EZ, and
    // vice versa.
    try {
        fs.rename(topEZFile, new Path(nestedEZDir, "movedTopEZFile"));
        fail("Shouldn't be able to rename between top EZ and nested EZ.");
    } catch (Exception e) {
        assertTrue(e.getMessage().contains("can't be moved from encryption zone " + topEZDir.toString() + " to encryption zone " + nestedEZDir.toString()));
    }
    try {
        fs.rename(nestedEZFile, new Path(topEZDir, "movedNestedEZFile"));
        fail("Shouldn't be able to rename between top EZ and nested EZ.");
    } catch (Exception e) {
        assertTrue(e.getMessage().contains("can't be moved from encryption zone " + nestedEZDir.toString() + " to encryption zone " + topEZDir.toString()));
    }
    // Verify that the nested EZ cannot be moved out of the top EZ.
    try {
        fs.rename(nestedEZFile, new Path(rootDir, "movedNestedEZFile"));
        fail("Shouldn't be able to move the nested EZ out of the top EZ.");
    } catch (Exception e) {
        assertTrue(e.getMessage().contains("can't be moved from an encryption zone"));
    }
    // Verify that a non-nested EZ cannot be moved into another EZ
    Path topEZ2Dir = new Path(rootDir, "topEZ2");
    fs.mkdir(topEZ2Dir, FsPermission.getDirDefault());
    fs.createEncryptionZone(topEZ2Dir, TOP_EZ_KEY);
    try {
        fs.rename(topEZ2Dir, new Path(topEZDir, "topEZ2"));
        fail("Shouldn't be able to move a non-nested EZ into another " + "existing EZ.");
    } catch (Exception e) {
        assertTrue(e.getMessage().contains("can't be moved into an encryption zone"));
    }
    try {
        fs.rename(topEZDir, new Path(rootDir, "newTopEZDir"));
    } catch (Exception e) {
        fail("Should be able to rename the root dir of an EZ.");
    }
    try {
        fs.rename(new Path(rootDir, "newTopEZDir/nestedEZDir"), new Path(rootDir, "newTopEZDir/newNestedEZDir"));
    } catch (Exception e) {
        fail("Should be able to rename the nested EZ dir within " + "the same top EZ.");
    }
}

/**
 * Test case where two directories are configured as NAME_AND_EDITS
 * and one of them fails to save storage. Since the edits and image
 * failure states are decoupled, the failure of image saving should
 * not prevent the purging of logs from that dir.
 */
@Test
public void testPurgingWithNameEditsDirAfterFailure() throws Exception {
    MiniDFSCluster cluster = null;
    Configuration conf = new HdfsConfiguration();
    conf.setLong(DFSConfigKeys.DFS_NAMENODE_NUM_EXTRA_EDITS_RETAINED_KEY, 0);
    File sd0 = new File(TEST_ROOT_DIR, "nn0");
    File sd1 = new File(TEST_ROOT_DIR, "nn1");
    File cd0 = new File(sd0, "current");
    File cd1 = new File(sd1, "current");
    conf.set(DFSConfigKeys.DFS_NAMENODE_NAME_DIR_KEY, Joiner.on(",").join(sd0, sd1));
    try {
        cluster = new MiniDFSCluster.Builder(conf).numDataNodes(0).manageNameDfsDirs(false).format(true).build();
        NameNode nn = cluster.getNameNode();
        doSaveNamespace(nn);
        LOG.info("After first save, images 0 and 2 should exist in both dirs");
        assertGlobEquals(cd0, "fsimage_\\d*", getImageFileName(0), getImageFileName(2));
        assertGlobEquals(cd1, "fsimage_\\d*", getImageFileName(0), getImageFileName(2));
        assertGlobEquals(cd0, "edits_.*", getFinalizedEditsFileName(1, 2), getInProgressEditsFileName(3));
        assertGlobEquals(cd1, "edits_.*", getFinalizedEditsFileName(1, 2), getInProgressEditsFileName(3));
        doSaveNamespace(nn);
        LOG.info("After second save, image 0 should be purged, " + "and image 4 should exist in both.");
        assertGlobEquals(cd0, "fsimage_\\d*", getImageFileName(2), getImageFileName(4));
        assertGlobEquals(cd1, "fsimage_\\d*", getImageFileName(2), getImageFileName(4));
        assertGlobEquals(cd0, "edits_.*", getFinalizedEditsFileName(3, 4), getInProgressEditsFileName(5));
        assertGlobEquals(cd1, "edits_.*", getFinalizedEditsFileName(3, 4), getInProgressEditsFileName(5));
        LOG.info("Failing first storage dir by chmodding it");
        assertEquals(0, FileUtil.chmod(cd0.getAbsolutePath(), "000"));
        doSaveNamespace(nn);
        LOG.info("Restoring accessibility of first storage dir");
        assertEquals(0, FileUtil.chmod(cd0.getAbsolutePath(), "755"));
        LOG.info("nothing should have been purged in first storage dir");
        assertGlobEquals(cd0, "fsimage_\\d*", getImageFileName(2), getImageFileName(4));
        assertGlobEquals(cd0, "edits_.*", getFinalizedEditsFileName(3, 4), getInProgressEditsFileName(5));
        LOG.info("fsimage_2 should be purged in second storage dir");
        assertGlobEquals(cd1, "fsimage_\\d*", getImageFileName(4), getImageFileName(6));
        assertGlobEquals(cd1, "edits_.*", getFinalizedEditsFileName(5, 6), getInProgressEditsFileName(7));
        LOG.info("On next save, we should purge logs from the failed dir," + " but not images, since the image directory is in failed state.");
        doSaveNamespace(nn);
        assertGlobEquals(cd1, "fsimage_\\d*", getImageFileName(6), getImageFileName(8));
        assertGlobEquals(cd1, "edits_.*", getFinalizedEditsFileName(7, 8), getInProgressEditsFileName(9));
        assertGlobEquals(cd0, "fsimage_\\d*", getImageFileName(2), getImageFileName(4));
        assertGlobEquals(cd0, "edits_.*", getInProgressEditsFileName(9));
    } finally {
        FileUtil.chmod(cd0.getAbsolutePath(), "755");
        LOG.info("Shutting down...");
        if (cluster != null) {
            cluster.shutdown();
        }
    }
}

