@Test
public void testBasics() {
    RollingWindow window = new RollingWindow(WINDOW_LEN, BUCKET_CNT);
    long time = 1;
    Assert.assertEquals("The initial sum of rolling window must be 0", 0, window.getSum(time));
    time = WINDOW_LEN + BUCKET_LEN * 3 / 2;
    Assert.assertEquals("The initial sum of rolling window must be 0", 0, window.getSum(time));
    window.incAt(time, 5);
    Assert.assertEquals("The sum of rolling window does not reflect the recent update", 5, window.getSum(time));
    time += BUCKET_LEN;
    window.incAt(time, 6);
    Assert.assertEquals("The sum of rolling window does not reflect the recent update", 11, window.getSum(time));
    time += WINDOW_LEN - BUCKET_LEN;
    Assert.assertEquals("The sum of rolling window does not reflect rolling effect", 6, window.getSum(time));
    time += BUCKET_LEN;
    Assert.assertEquals("The sum of rolling window does not reflect rolling effect", 0, window.getSum(time));
}

@Test
public void testReorderedAccess() {
    RollingWindow window = new RollingWindow(WINDOW_LEN, BUCKET_CNT);
    long time = 2 * WINDOW_LEN + BUCKET_LEN * 3 / 2;
    window.incAt(time, 5);
    time++;
    Assert.assertEquals("The sum of rolling window does not reflect the recent update", 5, window.getSum(time));
    long reorderedTime = time - 2 * BUCKET_LEN;
    window.incAt(reorderedTime, 6);
    Assert.assertEquals("The sum of rolling window does not reflect the reordered update", 11, window.getSum(time));
    time = reorderedTime + WINDOW_LEN;
    Assert.assertEquals("The sum of rolling window does not reflect rolling effect", 5, window.getSum(time));
}

@Test
public void testTops() {
    long time = WINDOW_LEN_MS + BUCKET_LEN * 3 / 2;
    for (int i = 0; i < users.length; i++) manager.recordMetric(time, "open", users[i], (i + 1) * 2);
    time++;
    for (int i = 0; i < users.length; i++) manager.recordMetric(time, "close", users[i], i + 1);
    time++;
    TopWindow tops = manager.snapshot(time);
    assertEquals("Unexpected number of ops", 2, tops.getOps().size());
    for (Op op : tops.getOps()) {
        final List<User> topUsers = op.getTopUsers();
        assertEquals("Unexpected number of users", N_TOP_USERS, topUsers.size());
        if (op.getOpType() == "open") {
            for (int i = 0; i < topUsers.size(); i++) {
                User user = topUsers.get(i);
                assertEquals("Unexpected count for user " + user.getUser(), (users.length - i) * 2, user.getCount());
            }
            // Closed form of sum(range(2,42,2))
            assertEquals("Unexpected total count for op", (2 + (users.length * 2)) * (users.length / 2), op.getTotalCount());
        }
    }
    // move the window forward not to see the "open" results
    time += WINDOW_LEN_MS - 2;
    tops = manager.snapshot(time);
    assertEquals("Unexpected number of ops", 1, tops.getOps().size());
    final Op op = tops.getOps().get(0);
    assertEquals("Should only see close ops", "close", op.getOpType());
    final List<User> topUsers = op.getTopUsers();
    for (int i = 0; i < topUsers.size(); i++) {
        User user = topUsers.get(i);
        assertEquals("Unexpected count for user " + user.getUser(), (users.length - i), user.getCount());
    }
    // Closed form of sum(range(1,21))
    assertEquals("Unexpected total count for op", (1 + users.length) * (users.length / 2), op.getTotalCount());
}

@Test
public void testDataLocality() throws Exception {
    final Configuration conf = WebHdfsTestUtil.createConf();
    final String[] racks = { RACK0, RACK0, RACK1, RACK1, RACK2, RACK2 };
    final int nDataNodes = racks.length;
    LOG.info("nDataNodes=" + nDataNodes + ", racks=" + Arrays.asList(racks));
    final MiniDFSCluster cluster = new MiniDFSCluster.Builder(conf).numDataNodes(nDataNodes).racks(racks).build();
    try {
        cluster.waitActive();
        final DistributedFileSystem dfs = cluster.getFileSystem();
        final NameNode namenode = cluster.getNameNode();
        final DatanodeManager dm = namenode.getNamesystem().getBlockManager().getDatanodeManager();
        LOG.info("dm=" + dm);
        final long blocksize = DFSConfigKeys.DFS_BLOCK_SIZE_DEFAULT;
        final String f = "/foo";
        {
            //test CREATE
            for (int i = 0; i < nDataNodes; i++) {
                //set client address to a particular datanode
                final DataNode dn = cluster.getDataNodes().get(i);
                final String ipAddr = dm.getDatanode(dn.getDatanodeId()).getIpAddr();
                //The chosen datanode must be the same as the client address
                final DatanodeInfo chosen = NamenodeWebHdfsMethods.chooseDatanode(namenode, f, PutOpParam.Op.CREATE, -1L, blocksize, null);
                Assert.assertEquals(ipAddr, chosen.getIpAddr());
            }
        }
        //create a file with one replica.
        final Path p = new Path(f);
        final FSDataOutputStream out = dfs.create(p, (short) 1);
        out.write(1);
        out.close();
        //get replica location.
        final LocatedBlocks locatedblocks = NameNodeAdapter.getBlockLocations(namenode, f, 0, 1);
        final List<LocatedBlock> lb = locatedblocks.getLocatedBlocks();
        Assert.assertEquals(1, lb.size());
        final DatanodeInfo[] locations = lb.get(0).getLocations();
        Assert.assertEquals(1, locations.length);
        final DatanodeInfo expected = locations[0];
        //For GETFILECHECKSUM, OPEN and APPEND,
        //the chosen datanode must be the same as the replica location.
        {
            //test GETFILECHECKSUM
            final DatanodeInfo chosen = NamenodeWebHdfsMethods.chooseDatanode(namenode, f, GetOpParam.Op.GETFILECHECKSUM, -1L, blocksize, null);
            Assert.assertEquals(expected, chosen);
        }
        {
            //test OPEN
            final DatanodeInfo chosen = NamenodeWebHdfsMethods.chooseDatanode(namenode, f, GetOpParam.Op.OPEN, 0, blocksize, null);
            Assert.assertEquals(expected, chosen);
        }
        {
            //test APPEND
            final DatanodeInfo chosen = NamenodeWebHdfsMethods.chooseDatanode(namenode, f, PostOpParam.Op.APPEND, -1L, blocksize, null);
            Assert.assertEquals(expected, chosen);
        }
    } finally {
        cluster.shutdown();
    }
}

