/**
 * Test complete(..) - verifies that the fileId in the request
 * matches that of the Inode.
 * This test checks that FileNotFoundException exception is thrown in case
 * the fileId does not match.
 */
@Test
public void testFileIdMismatch() throws IOException {
    Configuration conf = new HdfsConfiguration();
    MiniDFSCluster cluster = new MiniDFSCluster.Builder(conf).numDataNodes(3).build();
    DistributedFileSystem dfs = null;
    try {
        cluster.waitActive();
        dfs = cluster.getFileSystem();
        DFSClient client = dfs.dfs;
        final Path f = new Path("/testFileIdMismatch.txt");
        createFile(dfs, f, 3);
        long someOtherFileId = -1;
        try {
            cluster.getNameNodeRpc().complete(f.toString(), client.clientName, null, someOtherFileId);
            fail();
        } catch (FileNotFoundException e) {
            FileSystem.LOG.info("Caught Expected FileNotFoundException: ", e);
        }
    } finally {
        IOUtils.closeStream(dfs);
        cluster.shutdown();
    }
}

/**
 * 1. Check the blocks of old file are cleaned after creating with overwrite
 * 2. Restart NN, check the file
 * 3. Save new checkpoint and restart NN, check the file
 */
@Test(timeout = 120000)
public void testFileCreationWithOverwrite() throws Exception {
    Configuration conf = new Configuration();
    conf.setInt("dfs.blocksize", blockSize);
    MiniDFSCluster cluster = new MiniDFSCluster.Builder(conf).numDataNodes(3).build();
    DistributedFileSystem dfs = cluster.getFileSystem();
    try {
        dfs.mkdirs(new Path("/foo/dir"));
        String file = "/foo/dir/file";
        Path filePath = new Path(file);
        // Case 1: Create file with overwrite, check the blocks of old file
        // are cleaned after creating with overwrite
        NameNode nn = cluster.getNameNode();
        FSNamesystem fsn = NameNodeAdapter.getNamesystem(nn);
        BlockManager bm = fsn.getBlockManager();
        FSDataOutputStream out = dfs.create(filePath);
        byte[] oldData = AppendTestUtil.randomBytes(seed, fileSize);
        try {
            out.write(oldData);
        } finally {
            out.close();
        }
        LocatedBlocks oldBlocks = NameNodeAdapter.getBlockLocations(nn, file, 0, fileSize);
        assertBlocks(bm, oldBlocks, true);
        out = dfs.create(filePath, true);
        byte[] newData = AppendTestUtil.randomBytes(seed, fileSize);
        try {
            out.write(newData);
        } finally {
            out.close();
        }
        dfs.deleteOnExit(filePath);
        LocatedBlocks newBlocks = NameNodeAdapter.getBlockLocations(nn, file, 0, fileSize);
        assertBlocks(bm, newBlocks, true);
        assertBlocks(bm, oldBlocks, false);
        FSDataInputStream in = dfs.open(filePath);
        byte[] result = null;
        try {
            result = readAll(in);
        } finally {
            in.close();
        }
        Assert.assertArrayEquals(newData, result);
        // Case 2: Restart NN, check the file
        cluster.restartNameNode();
        nn = cluster.getNameNode();
        in = dfs.open(filePath);
        try {
            result = readAll(in);
        } finally {
            in.close();
        }
        Assert.assertArrayEquals(newData, result);
        // Case 3: Save new checkpoint and restart NN, check the file
        NameNodeAdapter.enterSafeMode(nn, false);
        NameNodeAdapter.saveNamespace(nn);
        cluster.restartNameNode();
        nn = cluster.getNameNode();
        in = dfs.open(filePath);
        try {
            result = readAll(in);
        } finally {
            in.close();
        }
        Assert.assertArrayEquals(newData, result);
    } finally {
        if (dfs != null) {
            dfs.close();
        }
        if (cluster != null) {
            cluster.shutdown();
        }
    }
}

/**
 * Test lease recovery Triggered by DFSClient.
 */
@Test
public void testClientTriggeredLeaseRecovery() throws Exception {
    final int REPLICATION = 3;
    Configuration conf = new HdfsConfiguration();
    conf.setInt(DFSConfigKeys.DFS_DATANODE_HANDLER_COUNT_KEY, 1);
    conf.setInt(DFSConfigKeys.DFS_REPLICATION_KEY, REPLICATION);
    MiniDFSCluster cluster = new MiniDFSCluster.Builder(conf).numDataNodes(REPLICATION).build();
    try {
        final FileSystem fs = cluster.getFileSystem();
        final Path dir = new Path("/wrwelkj");
        SlowWriter[] slowwriters = new SlowWriter[10];
        for (int i = 0; i < slowwriters.length; i++) {
            slowwriters[i] = new SlowWriter(fs, new Path(dir, "file" + i));
        }
        try {
            for (int i = 0; i < slowwriters.length; i++) {
                slowwriters[i].start();
            }
            // let writers get started
            Thread.sleep(1000);
            //stop a datanode, it should have least recover.
            cluster.stopDataNode(AppendTestUtil.nextInt(REPLICATION));
            //let the slow writer writes a few more seconds
            System.out.println("Wait a few seconds");
            Thread.sleep(5000);
        } finally {
            for (int i = 0; i < slowwriters.length; i++) {
                if (slowwriters[i] != null) {
                    slowwriters[i].running = false;
                    slowwriters[i].interrupt();
                }
            }
            for (int i = 0; i < slowwriters.length; i++) {
                if (slowwriters[i] != null) {
                    slowwriters[i].join();
                }
            }
        }
        //Verify the file
        System.out.println("Verify the file");
        for (int i = 0; i < slowwriters.length; i++) {
            System.out.println(slowwriters[i].filepath + ": length=" + fs.getFileStatus(slowwriters[i].filepath).getLen());
            FSDataInputStream in = null;
            try {
                in = fs.open(slowwriters[i].filepath);
                for (int j = 0, x; (x = in.read()) != -1; j++) {
                    assertEquals(j, x);
                }
            } finally {
                IOUtils.closeStream(in);
            }
        }
    } finally {
        if (cluster != null) {
            cluster.shutdown();
        }
    }
}

@Test
public void testFileCreationDeleteParent() throws IOException {
    Configuration conf = new HdfsConfiguration();
    // 2s
    final int MAX_IDLE_TIME = 2000;
    conf.setInt("ipc.client.connection.maxidletime", MAX_IDLE_TIME);
    conf.setInt(DFSConfigKeys.DFS_NAMENODE_HEARTBEAT_RECHECK_INTERVAL_KEY, 1000);
    conf.setInt(DFSConfigKeys.DFS_HEARTBEAT_INTERVAL_KEY, 1);
    // create cluster
    MiniDFSCluster cluster = new MiniDFSCluster.Builder(conf).build();
    FileSystem fs = null;
    try {
        cluster.waitActive();
        fs = cluster.getFileSystem();
        final int nnport = cluster.getNameNodePort();
        // create file1.
        Path dir = new Path("/foo");
        Path file1 = new Path(dir, "file1");
        FSDataOutputStream stm1 = TestFileCreation.createFile(fs, file1, 1);
        System.out.println("testFileCreationDeleteParent: " + "Created file " + file1);
        TestFileCreation.writeFile(stm1, 1000);
        stm1.hflush();
        // create file2.
        Path file2 = new Path("/file2");
        FSDataOutputStream stm2 = TestFileCreation.createFile(fs, file2, 1);
        System.out.println("testFileCreationDeleteParent: " + "Created file " + file2);
        TestFileCreation.writeFile(stm2, 1000);
        stm2.hflush();
        // rm dir
        fs.delete(dir, true);
        // restart cluster with the same namenode port as before.
        // This ensures that leases are persisted in fsimage.
        cluster.shutdown();
        try {
            Thread.sleep(2 * MAX_IDLE_TIME);
        } catch (InterruptedException e) {
        }
        cluster = new MiniDFSCluster.Builder(conf).nameNodePort(nnport).format(false).build();
        cluster.waitActive();
        // restart cluster yet again. This triggers the code to read in
        // persistent leases from fsimage.
        cluster.shutdown();
        try {
            Thread.sleep(5000);
        } catch (InterruptedException e) {
        }
        cluster = new MiniDFSCluster.Builder(conf).nameNodePort(nnport).format(false).build();
        cluster.waitActive();
        fs = cluster.getFileSystem();
        assertTrue(!fs.exists(file1));
        assertTrue(fs.exists(file2));
    } finally {
        fs.close();
        cluster.shutdown();
    }
}

/**
 * This test creates three empty files and lets their leases expire.
 * This triggers release of the leases.
 * The empty files are supposed to be closed by that
 * without causing ConcurrentModificationException.
 */
@Test
public void testLeaseExpireEmptyFiles() throws Exception {
    final Thread.UncaughtExceptionHandler oldUEH = Thread.getDefaultUncaughtExceptionHandler();
    Thread.setDefaultUncaughtExceptionHandler(new Thread.UncaughtExceptionHandler() {

        @Override
        public void uncaughtException(Thread t, Throwable e) {
            if (e instanceof ConcurrentModificationException) {
                LeaseManager.LOG.error("t=" + t, e);
                isConcurrentModificationException = true;
            }
        }
    });
    System.out.println("testLeaseExpireEmptyFiles start");
    final long leasePeriod = 1000;
    final int DATANODE_NUM = 3;
    final Configuration conf = new HdfsConfiguration();
    conf.setInt(DFSConfigKeys.DFS_NAMENODE_HEARTBEAT_RECHECK_INTERVAL_KEY, 1000);
    conf.setInt(DFSConfigKeys.DFS_HEARTBEAT_INTERVAL_KEY, 1);
    // create cluster
    MiniDFSCluster cluster = new MiniDFSCluster.Builder(conf).numDataNodes(DATANODE_NUM).build();
    try {
        cluster.waitActive();
        DistributedFileSystem dfs = cluster.getFileSystem();
        // create a new file.
        TestFileCreation.createFile(dfs, new Path("/foo"), DATANODE_NUM);
        TestFileCreation.createFile(dfs, new Path("/foo2"), DATANODE_NUM);
        TestFileCreation.createFile(dfs, new Path("/foo3"), DATANODE_NUM);
        // set the soft and hard limit to be 1 second so that the
        // namenode triggers lease recovery
        cluster.setLeasePeriod(leasePeriod, leasePeriod);
        // wait for the lease to expire
        try {
            Thread.sleep(5 * leasePeriod);
        } catch (InterruptedException e) {
        }
        assertFalse(isConcurrentModificationException);
    } finally {
        Thread.setDefaultUncaughtExceptionHandler(oldUEH);
        cluster.shutdown();
    }
}

/**
 * Tests the fileLength when we sync the file and restart the cluster and
 * Datanodes not report to Namenode yet.
 */
@Test(timeout = 60000)
public void testFileLengthWithHSyncAndClusterRestartWithOutDNsRegister() throws Exception {
    final Configuration conf = new HdfsConfiguration();
    // create cluster
    conf.setInt(DFSConfigKeys.DFS_BLOCK_SIZE_KEY, 512);
    final MiniDFSCluster cluster = new MiniDFSCluster.Builder(conf).numDataNodes(2).build();
    HdfsDataInputStream in = null;
    try {
        Path path = new Path("/tmp/TestFileLengthOnClusterRestart", "test");
        DistributedFileSystem dfs = cluster.getFileSystem();
        FSDataOutputStream out = dfs.create(path);
        int fileLength = 1030;
        out.write(new byte[fileLength]);
        out.hsync();
        cluster.restartNameNode();
        cluster.waitActive();
        in = (HdfsDataInputStream) dfs.open(path, 1024);
        // Verify the length when we just restart NN. DNs will register
        // immediately.
        Assert.assertEquals(fileLength, in.getVisibleLength());
        cluster.shutdownDataNodes();
        cluster.restartNameNode(false);
        // This is just for ensuring NN started.
        verifyNNIsInSafeMode(dfs);
        try {
            in = (HdfsDataInputStream) dfs.open(path);
            Assert.fail("Expected IOException");
        } catch (IOException e) {
            Assert.assertTrue(e.getLocalizedMessage().indexOf("Name node is in safe mode") >= 0);
        }
    } finally {
        if (null != in) {
            in.close();
        }
        cluster.shutdown();
    }
}

/**
 * Test calling getFileInfo directly on the client
 */
@Test
public void testGetFileInfo() throws IOException {
    // Check that / exists
    Path path = new Path("/");
    assertTrue("/ should be a directory", fs.getFileStatus(path).isDirectory());
    // Make sure getFileInfo returns null for files which do not exist
    HdfsFileStatus fileInfo = dfsClient.getFileInfo("/noSuchFile");
    assertEquals("Non-existant file should result in null", null, fileInfo);
    Path path1 = new Path("/name1");
    Path path2 = new Path("/name1/name2");
    assertTrue(fs.mkdirs(path1));
    FSDataOutputStream out = fs.create(path2, false);
    out.close();
    fileInfo = dfsClient.getFileInfo(path1.toString());
    assertEquals(1, fileInfo.getChildrenNum());
    fileInfo = dfsClient.getFileInfo(path2.toString());
    assertEquals(0, fileInfo.getChildrenNum());
    // Test getFileInfo throws the right exception given a non-absolute path.
    try {
        dfsClient.getFileInfo("non-absolute");
        fail("getFileInfo for a non-absolute path did not throw IOException");
    } catch (RemoteException re) {
        assertTrue("Wrong exception for invalid file name", re.toString().contains("Invalid file name"));
    }
}

