/**
 * Test of equals method, of class TaskID.
 */
@Test
public void testEquals() {
    JobID jobId1 = new JobID("1234", 1);
    JobID jobId2 = new JobID("2345", 2);
    TaskID taskId1 = new TaskID(jobId1, TaskType.MAP, 0);
    TaskID taskId2 = new TaskID(jobId1, TaskType.MAP, 0);
    assertTrue("The equals() method reported two equal task IDs were not equal", taskId1.equals(taskId2));
    taskId2 = new TaskID(jobId2, TaskType.MAP, 0);
    assertFalse("The equals() method reported two task IDs with different " + "job IDs were equal", taskId1.equals(taskId2));
    taskId2 = new TaskID(jobId1, TaskType.MAP, 1);
    assertFalse("The equals() method reported two task IDs with different IDs " + "were equal", taskId1.equals(taskId2));
    TaskType[] types = TaskType.values();
    for (int i = 0; i < types.length; i++) {
        for (int j = 0; j < types.length; j++) {
            taskId1 = new TaskID(jobId1, types[i], 0);
            taskId2 = new TaskID(jobId1, types[j], 0);
            if (i == j) {
                assertTrue("The equals() method reported two equal task IDs were not " + "equal", taskId1.equals(taskId2));
            } else {
                assertFalse("The equals() method reported two task IDs with " + "different types were equal", taskId1.equals(taskId2));
            }
        }
    }
    assertFalse("The equals() method matched against a JobID object", taskId1.equals(jobId1));
    assertFalse("The equals() method matched against a null object", taskId1.equals(null));
}

/**
 * Test of compareTo method, of class TaskID.
 */
@Test
public void testCompareTo() {
    JobID jobId = new JobID("1234", 1);
    TaskID taskId1 = new TaskID(jobId, TaskType.REDUCE, 0);
    TaskID taskId2 = new TaskID(jobId, TaskType.REDUCE, 0);
    assertEquals("The compareTo() method returned non-zero for two equal " + "task IDs", 0, taskId1.compareTo(taskId2));
    taskId2 = new TaskID(jobId, TaskType.MAP, 1);
    assertTrue("The compareTo() method did not weigh task type more than task " + "ID", taskId1.compareTo(taskId2) > 0);
    TaskType[] types = TaskType.values();
    for (int i = 0; i < types.length; i++) {
        for (int j = 0; j < types.length; j++) {
            taskId1 = new TaskID(jobId, types[i], 0);
            taskId2 = new TaskID(jobId, types[j], 0);
            if (i == j) {
                assertEquals("The compareTo() method returned non-zero for two equal " + "task IDs", 0, taskId1.compareTo(taskId2));
            } else if (i < j) {
                assertTrue("The compareTo() method did not order " + types[i] + " before " + types[j], taskId1.compareTo(taskId2) < 0);
            } else {
                assertTrue("The compareTo() method did not order " + types[i] + " after " + types[j], taskId1.compareTo(taskId2) > 0);
            }
        }
    }
    try {
        taskId1.compareTo(jobId);
        fail("The compareTo() method allowed comparison to a JobID object");
    } catch (ClassCastException ex) {
        // Expected
    }
    try {
        taskId1.compareTo(null);
        fail("The compareTo() method allowed comparison to a null object");
    } catch (NullPointerException ex) {
        // Expected
    }
}

