@Test
public void testAppendOption() {
    Configuration conf = new Configuration();
    Assert.assertFalse(conf.getBoolean(DistCpOptionSwitch.APPEND.getConfigLabel(), false));
    Assert.assertFalse(conf.getBoolean(DistCpOptionSwitch.SYNC_FOLDERS.getConfigLabel(), false));
    DistCpOptions options = OptionsParser.parse(new String[] { "-update", "-append", "hdfs://localhost:9820/source/first", "hdfs://localhost:9820/target/" });
    options.appendToConf(conf);
    Assert.assertTrue(conf.getBoolean(DistCpOptionSwitch.APPEND.getConfigLabel(), false));
    Assert.assertTrue(conf.getBoolean(DistCpOptionSwitch.SYNC_FOLDERS.getConfigLabel(), false));
    // make sure -append is only valid when -update is specified
    try {
        OptionsParser.parse(new String[] { "-append", "hdfs://localhost:9820/source/first", "hdfs://localhost:9820/target/" });
        fail("Append should fail if update option is not specified");
    } catch (IllegalArgumentException e) {
        GenericTestUtils.assertExceptionContains("Append is valid only with update options", e);
    }
    // make sure -append is invalid when skipCrc is specified
    try {
        OptionsParser.parse(new String[] { "-append", "-update", "-skipcrccheck", "hdfs://localhost:9820/source/first", "hdfs://localhost:9820/target/" });
        fail("Append should fail if skipCrc option is specified");
    } catch (IllegalArgumentException e) {
        GenericTestUtils.assertExceptionContains("Append is disallowed when skipping CRC", e);
    }
}

@Test
public void testDiffOption() {
    Configuration conf = new Configuration();
    Assert.assertFalse(conf.getBoolean(DistCpOptionSwitch.DIFF.getConfigLabel(), false));
    DistCpOptions options = OptionsParser.parse(new String[] { "-update", "-diff", "s1", "s2", "hdfs://localhost:9820/source/first", "hdfs://localhost:9820/target/" });
    options.appendToConf(conf);
    Assert.assertTrue(conf.getBoolean(DistCpOptionSwitch.DIFF.getConfigLabel(), false));
    Assert.assertTrue(options.shouldUseDiff());
    Assert.assertEquals("s1", options.getFromSnapshot());
    Assert.assertEquals("s2", options.getToSnapshot());
    options = OptionsParser.parse(new String[] { "-diff", "s1", ".", "-update", "hdfs://localhost:9820/source/first", "hdfs://localhost:9820/target/" });
    options.appendToConf(conf);
    Assert.assertTrue(conf.getBoolean(DistCpOptionSwitch.DIFF.getConfigLabel(), false));
    Assert.assertTrue(options.shouldUseDiff());
    Assert.assertEquals("s1", options.getFromSnapshot());
    Assert.assertEquals(".", options.getToSnapshot());
    // -diff requires two option values
    try {
        OptionsParser.parse(new String[] { "-diff", "s1", "-update", "hdfs://localhost:9820/source/first", "hdfs://localhost:9820/target/" });
        fail("-diff should fail with only one snapshot name");
    } catch (IllegalArgumentException e) {
        GenericTestUtils.assertExceptionContains("Must provide both the starting and ending snapshot names", e);
    }
    // make sure -diff is only valid when -update is specified
    try {
        OptionsParser.parse(new String[] { "-diff", "s1", "s2", "hdfs://localhost:9820/source/first", "hdfs://localhost:9820/target/" });
        fail("-diff should fail if -update option is not specified");
    } catch (IllegalArgumentException e) {
        GenericTestUtils.assertExceptionContains("Diff is valid only with update options", e);
    }
    try {
        options = OptionsParser.parse(new String[] { "-diff", "s1", "s2", "-update", "-delete", "hdfs://localhost:9820/source/first", "hdfs://localhost:9820/target/" });
        assertFalse("-delete should be ignored when -diff is specified", options.shouldDeleteMissing());
    } catch (IllegalArgumentException e) {
        fail("Got unexpected IllegalArgumentException: " + e.getMessage());
    }
    try {
        options = OptionsParser.parse(new String[] { "-diff", "s1", "s2", "-delete", "hdfs://localhost:9820/source/first", "hdfs://localhost:9820/target/" });
        fail("-diff should fail if -update option is not specified");
    } catch (IllegalArgumentException e) {
        assertFalse("-delete should be ignored when -diff is specified", options.shouldDeleteMissing());
        GenericTestUtils.assertExceptionContains("Diff is valid only with update options", e);
    }
    try {
        OptionsParser.parse(new String[] { "-diff", "s1", "s2", "-delete", "-overwrite", "hdfs://localhost:9820/source/first", "hdfs://localhost:9820/target/" });
        fail("-diff should fail if -update option is not specified");
    } catch (IllegalArgumentException e) {
        GenericTestUtils.assertExceptionContains("Diff is valid only with update options", e);
    }
}

