        ByteArrayInputStream in = new ByteArrayInputStream(out.toByteArray());
        TypedBytesInput tbinput = new TypedBytesInput(new DataInputStream(in));
        int counter = 0;
        Object key = tbinput.read();
        while (key != null) {
            // offset
