        try {
            client.submitApplication(context);
        } catch (YarnException e) {
            Assert.fail("Exception is not expected.");
        } catch (IOException e) {
            Assert.fail("Exception is not expected.");
        }
        verify(((MockYarnClient) client).mockReport, times(4 * i + 4)).getYarnApplicationState();
    }
    client.stop();
}

