    } catch (Exception e) {
        Assert.fail("Exception is not expected." + e);
    }
}

@Test
public void testGetRMDelegationTokenService() {
    String defaultRMAddress = YarnConfiguration.DEFAULT_RM_ADDRESS;
    YarnConfiguration conf = new YarnConfiguration();
