/**
 * Test to verify that an OPPORTUNISTIC container is killed when
 * a GUARANTEED container arrives and all the Node Resources are used up
 *
 * For this specific test case, 4 containers are requested (last one being
 * guaranteed). Assumptions :
 * 1) The first OPPORTUNISTIC Container will start running
 * 2) The second and third OPP containers will be queued
 * 3) When the GUARANTEED container comes in, the running OPP container
 *    will be killed to make room
 * 4) After the GUARANTEED container finishes, the remaining 2 OPP
 *    containers will be dequeued and run.
 * 5) Only the first OPP container will be killed.
 *
 * @throws Exception
 */
@Test
public void testSimpleOpportunisticContainer() throws Exception {
    shouldDeleteWait = true;
    containerManager.start();
    // ////// Create the resources for the container
    File dir = new File(tmpDir, "dir");
    dir.mkdirs();
    File file = new File(dir, "file");
    PrintWriter fileWriter = new PrintWriter(file);
    fileWriter.write("Hello World!");
    fileWriter.close();
    // ////// Construct the container-spec.
    ContainerLaunchContext containerLaunchContext = recordFactory.newRecordInstance(ContainerLaunchContext.class);
    URL resource_alpha = ConverterUtils.getYarnUrlFromPath(localFS.makeQualified(new Path(file.getAbsolutePath())));
    LocalResource rsrc_alpha = recordFactory.newRecordInstance(LocalResource.class);
    rsrc_alpha.setResource(resource_alpha);
    rsrc_alpha.setSize(-1);
    rsrc_alpha.setVisibility(LocalResourceVisibility.APPLICATION);
    rsrc_alpha.setType(LocalResourceType.FILE);
    rsrc_alpha.setTimestamp(file.lastModified());
    String destinationFile = "dest_file";
    Map<String, LocalResource> localResources = new HashMap<String, LocalResource>();
    localResources.put(destinationFile, rsrc_alpha);
    containerLaunchContext.setLocalResources(localResources);
    // Start 3 OPPORTUNISTIC containers and 1 GUARANTEED container
    List<StartContainerRequest> list = new ArrayList<>();
    list.add(StartContainerRequest.newInstance(containerLaunchContext, createContainerToken(createContainerId(0), DUMMY_RM_IDENTIFIER, context.getNodeId(), user, BuilderUtils.newResource(1024, 1), context.getContainerTokenSecretManager(), null, ExecutionType.OPPORTUNISTIC)));
    list.add(StartContainerRequest.newInstance(containerLaunchContext, createContainerToken(createContainerId(1), DUMMY_RM_IDENTIFIER, context.getNodeId(), user, BuilderUtils.newResource(1024, 1), context.getContainerTokenSecretManager(), null, ExecutionType.OPPORTUNISTIC)));
    list.add(StartContainerRequest.newInstance(containerLaunchContext, createContainerToken(createContainerId(2), DUMMY_RM_IDENTIFIER, context.getNodeId(), user, BuilderUtils.newResource(1024, 1), context.getContainerTokenSecretManager(), null, ExecutionType.OPPORTUNISTIC)));
    // GUARANTEED
    list.add(StartContainerRequest.newInstance(containerLaunchContext, createContainerToken(createContainerId(3), DUMMY_RM_IDENTIFIER, context.getNodeId(), user, BuilderUtils.newResource(1024, 1), context.getContainerTokenSecretManager(), null, ExecutionType.GUARANTEED)));
    StartContainersRequest allRequests = StartContainersRequest.newInstance(list);
    containerManager.startContainers(allRequests);
    Thread.sleep(10000);
    List<ContainerId> statList = new ArrayList<ContainerId>();
    for (int i = 0; i < 4; i++) {
        statList.add(createContainerId(i));
    }
    GetContainerStatusesRequest statRequest = GetContainerStatusesRequest.newInstance(statList);
    List<ContainerStatus> containerStatuses = containerManager.getContainerStatuses(statRequest).getContainerStatuses();
    for (ContainerStatus status : containerStatuses) {
        // Ensure that the first opportunistic container is killed
        if (status.getContainerId().equals(createContainerId(0))) {
            Assert.assertTrue(status.getDiagnostics().contains("Container killed by the ApplicationMaster"));
        }
        System.out.println("\nStatus : [" + status + "]\n");
    }
}

// To verify whether we could load class from customized class path.
// We would use ServiceC in this test. Also create a separate jar file
// including ServiceC class, and add this jar to customized directory.
// By setting some proper configurations, we should load ServiceC class
// from customized class path.
@Test(timeout = 15000)
public void testCustomizedAuxServiceClassPath() throws Exception {
    // verify that we can load AuxService Class from default Class path
    Configuration conf = new YarnConfiguration();
    conf.setStrings(YarnConfiguration.NM_AUX_SERVICES, new String[] { "ServiceC" });
    conf.setClass(String.format(YarnConfiguration.NM_AUX_SERVICE_FMT, "ServiceC"), ServiceC.class, Service.class);
    @SuppressWarnings("resource")
    AuxServices aux = new AuxServices();
    aux.init(conf);
    aux.start();
    Map<String, ByteBuffer> meta = aux.getMetaData();
    String auxName = "";
    Set<String> defaultAuxClassPath = null;
    Assert.assertTrue(meta.size() == 1);
    for (Entry<String, ByteBuffer> i : meta.entrySet()) {
        auxName = i.getKey();
        String auxClassPath = Charsets.UTF_8.decode(i.getValue()).toString();
        defaultAuxClassPath = new HashSet<String>(Arrays.asList(StringUtils.getTrimmedStrings(auxClassPath)));
    }
    Assert.assertTrue(auxName.equals("ServiceC"));
    aux.serviceStop();
    // create a new jar file, and configure it as customized class path
    // for this AuxService, and make sure that we could load the class
    // from this configured customized class path
    File rootDir = GenericTestUtils.getTestDir(getClass().getSimpleName());
    if (!rootDir.exists()) {
        rootDir.mkdirs();
    }
    File testJar = null;
    try {
        testJar = JarFinder.makeClassLoaderTestJar(this.getClass(), rootDir, "test-runjar.jar", 2048, ServiceC.class.getName());
        conf = new YarnConfiguration();
        conf.setStrings(YarnConfiguration.NM_AUX_SERVICES, new String[] { "ServiceC" });
        conf.set(String.format(YarnConfiguration.NM_AUX_SERVICE_FMT, "ServiceC"), ServiceC.class.getName());
        conf.set(String.format(YarnConfiguration.NM_AUX_SERVICES_CLASSPATH, "ServiceC"), testJar.getAbsolutePath());
        // remove "-org.apache.hadoop." from system classes
        String systemClasses = "-org.apache.hadoop." + "," + ApplicationClassLoader.SYSTEM_CLASSES_DEFAULT;
        conf.set(String.format(YarnConfiguration.NM_AUX_SERVICES_SYSTEM_CLASSES, "ServiceC"), systemClasses);
        aux = new AuxServices();
        aux.init(conf);
        aux.start();
        meta = aux.getMetaData();
        Assert.assertTrue(meta.size() == 1);
        Set<String> customizedAuxClassPath = null;
        for (Entry<String, ByteBuffer> i : meta.entrySet()) {
            Assert.assertTrue(auxName.equals(i.getKey()));
            String classPath = Charsets.UTF_8.decode(i.getValue()).toString();
            customizedAuxClassPath = new HashSet<String>(Arrays.asList(StringUtils.getTrimmedStrings(classPath)));
            Assert.assertTrue(classPath.contains(testJar.getName()));
        }
        aux.stop();
        // Verify that we do not have any overlap between customized class path
        // and the default class path.
        Set<String> mutalClassPath = Sets.intersection(defaultAuxClassPath, customizedAuxClassPath);
        Assert.assertTrue(mutalClassPath.isEmpty());
    } finally {
        if (testJar != null) {
            testJar.delete();
            rootDir.delete();
        }
    }
}

@Test
public void testAuxEventDispatch() {
    Configuration conf = new Configuration();
    conf.setStrings(YarnConfiguration.NM_AUX_SERVICES, new String[] { "Asrv", "Bsrv" });
    conf.setClass(String.format(YarnConfiguration.NM_AUX_SERVICE_FMT, "Asrv"), ServiceA.class, Service.class);
    conf.setClass(String.format(YarnConfiguration.NM_AUX_SERVICE_FMT, "Bsrv"), ServiceB.class, Service.class);
    conf.setInt("A.expected.init", 1);
    conf.setInt("B.expected.stop", 1);
    final AuxServices aux = new AuxServices();
    aux.init(conf);
    aux.start();
    ApplicationId appId1 = ApplicationId.newInstance(0, 65);
    ByteBuffer buf = ByteBuffer.allocate(6);
    buf.putChar('A');
    buf.putInt(65);
    buf.flip();
    AuxServicesEvent event = new AuxServicesEvent(AuxServicesEventType.APPLICATION_INIT, "user0", appId1, "Asrv", buf);
    aux.handle(event);
    ApplicationId appId2 = ApplicationId.newInstance(0, 66);
    event = new AuxServicesEvent(AuxServicesEventType.APPLICATION_STOP, "user0", appId2, "Bsrv", null);
    // verify all services got the stop event
    aux.handle(event);
    Collection<AuxiliaryService> servs = aux.getServices();
    for (AuxiliaryService serv : servs) {
        ArrayList<Integer> appIds = ((LightService) serv).getAppIdsStopped();
        assertEquals("app not properly stopped", 1, appIds.size());
        assertTrue("wrong app stopped", appIds.contains((Integer) 66));
    }
    for (AuxiliaryService serv : servs) {
        assertNull(((LightService) serv).containerId);
        assertNull(((LightService) serv).resource);
    }
    ApplicationAttemptId attemptId = ApplicationAttemptId.newInstance(appId1, 1);
    ContainerTokenIdentifier cti = new ContainerTokenIdentifier(ContainerId.newContainerId(attemptId, 1), "", "", Resource.newInstance(1, 1), 0, 0, 0, Priority.newInstance(0), 0);
    Context context = mock(Context.class);
    Container container = new ContainerImpl(new YarnConfiguration(), null, null, null, null, cti, context);
    ContainerId containerId = container.getContainerId();
    Resource resource = container.getResource();
    event = new AuxServicesEvent(AuxServicesEventType.CONTAINER_INIT, container);
    aux.handle(event);
    for (AuxiliaryService serv : servs) {
        assertEquals(containerId, ((LightService) serv).containerId);
        assertEquals(resource, ((LightService) serv).resource);
        ((LightService) serv).containerId = null;
        ((LightService) serv).resource = null;
    }
    event = new AuxServicesEvent(AuxServicesEventType.CONTAINER_STOP, container);
    aux.handle(event);
    for (AuxiliaryService serv : servs) {
        assertEquals(containerId, ((LightService) serv).containerId);
        assertEquals(resource, ((LightService) serv).resource);
    }
}

@Test
public void testAuxServices() {
    Configuration conf = new Configuration();
    conf.setStrings(YarnConfiguration.NM_AUX_SERVICES, new String[] { "Asrv", "Bsrv" });
    conf.setClass(String.format(YarnConfiguration.NM_AUX_SERVICE_FMT, "Asrv"), ServiceA.class, Service.class);
    conf.setClass(String.format(YarnConfiguration.NM_AUX_SERVICE_FMT, "Bsrv"), ServiceB.class, Service.class);
    final AuxServices aux = new AuxServices();
    aux.init(conf);
    int latch = 1;
    for (Service s : aux.getServices()) {
        assertEquals(INITED, s.getServiceState());
        if (s instanceof ServiceA) {
            latch *= 2;
        } else if (s instanceof ServiceB) {
            latch *= 3;
        } else
            fail("Unexpected service type " + s.getClass());
    }
    assertEquals("Invalid mix of services", 6, latch);
    aux.start();
    for (Service s : aux.getServices()) {
        assertEquals(STARTED, s.getServiceState());
    }
    aux.stop();
    for (Service s : aux.getServices()) {
        assertEquals(STOPPED, s.getServiceState());
    }
}

