@Test
public void testNodePartitionPreemptionRespectGuaranteedCapacity() throws IOException {
    /**
     * The simplest test of node label, Queue structure is:
     *
     * <pre>
     *       root
     *       /  \
     *      a    b
     * </pre>
     *
     * Both a/b can access x, and guaranteed capacity of them is 50:50. Two
     * nodes, n1 has 100 x, n2 has 100 NO_LABEL 4 applications in the cluster,
     * app1/app2 in a, and app3/app4 in b.
     * app1 uses 80 x, app2 uses 20 NO_LABEL, app3 uses 20 x, app4 uses 80 NO_LABEL.
     * Both a/b have 50 pending resource for x and NO_LABEL
     *
     * After preemption, it should preempt 30 from app1, and 30 from app4.
     */
    String labelsConfig = // default partition
    "=100,true;" + // partition=x
    "x=100,true";
    String nodesConfig = // n1 has partition=x
    "n1=x;" + // n2 is default partition
    "n2=";
    String queuesConfig = // guaranteed,max,used,pending
    //root
    "root(=[100 100 100 100],x=[100 100 100 100]);" + // a
    "-a(=[50 100 20 50],x=[50 100 80 50]);" + // b
    "-b(=[50 100 80 50],x=[50 100 20 50])";
    String appsConfig = //queueName\t(priority,resource,host,expression,#repeat,reserved)
    // app1 in a
    "a\t" + // 80 * x in n1
    "(1,1,n1,x,80,false);" + // app2 in a
    "a\t" + // 20 default in n2
    "(1,1,n2,,20,false);" + // app3 in b
    "b\t" + // 80 * x in n1
    "(1,1,n1,x,20,false);" + // app4 in b
    "b\t" + // 20 default in n2
    "(1,1,n2,,80,false)";
    buildEnv(labelsConfig, nodesConfig, queuesConfig, appsConfig);
    policy.editSchedule();
    // 30 preempted from app1, 30 preempted from app4, and nothing preempted
    // from app2/app3
    verify(mDisp, times(30)).handle(argThat(new IsPreemptionRequestFor(getAppAttemptId(1))));
    verify(mDisp, times(30)).handle(argThat(new IsPreemptionRequestFor(getAppAttemptId(4))));
    verify(mDisp, never()).handle(argThat(new IsPreemptionRequestFor(getAppAttemptId(2))));
    verify(mDisp, never()).handle(argThat(new IsPreemptionRequestFor(getAppAttemptId(3))));
}

