@Test
public void testNodePartitionNonAccessibleQueuesSharePartitionedResource() throws IOException {
    /**
     * Queue structure is:
     *
     * <pre>
     *           root
     *        _________
     *       /  |   |  \
     *      a   b   c   d
     * </pre>
     *
     * a/b can access x, their capacity is 50:50 c/d cannot access x.
     *
     * a uses 0, wants 30
     * b(app1) uses 30, wants 0
     * c(app2)&d(app3) use 35, wants 50
     *
     * After preemption, c/d will be preempted 15 containers, because idle
     * resource = 100 - 30 (which is used by b) - 30 (which is asked by a) = 40
     * will be divided by c/d, so each of c/d get 20.
     */
    String labelsConfig = // default partition
    "=100,true;" + // partition=x
    "x=100,false";
    String nodesConfig = // n1 has partition=x
    "n1=x;" + // n2 is default partition
    "n2=";
    String queuesConfig = // guaranteed,max,used,pending
    //root
    "root(=[100 100 100 100],x=[100 100 100 100]);" + // a
    "-a(=[25 100 0 0],x=[50 100 0 30]);" + // b
    "-b(=[25 100 0 0],x=[50 100 30 0]);" + //c
    "-c(=[25 100 1 0],x=[0 0 35 50]);" + //d
    "-d(=[25 100 1 0],x=[0 0 35 50])";
    String appsConfig = //queueName\t(priority,resource,host,expression,#repeat,reserved)
    // app1 in b
    "b\t" + // 50x in n1
    "(1,1,n1,x,30,false);" + // app2 in c
    "c\t" + // AM container (in n2)
    "(1,1,n2,,1,false)" + // 30x in n1 (ignore exclusivity)
    "(1,1,n1,,30,false);" + // app3 in d
    "d\t" + // AM container (in n2)
    "(1,1,n2,,1,false)" + // 30x in n1 (ignore exclusivity)
    "(1,1,n1,,30,false)";
    buildEnv(labelsConfig, nodesConfig, queuesConfig, appsConfig);
    policy.editSchedule();
    // 15 will be preempted app2/app3
    verify(mDisp, times(15)).handle(argThat(new IsPreemptionRequestFor(getAppAttemptId(2))));
    verify(mDisp, times(15)).handle(argThat(new IsPreemptionRequestFor(getAppAttemptId(3))));
    verify(mDisp, never()).handle(argThat(new IsPreemptionRequestFor(getAppAttemptId(1))));
}

