@Test
public void testReservedSelectorSkipsAMContainer() throws IOException {
    /**
     * Queue structure is:
     *
     * <pre>
     *       root
     *       /  \
     *      a    b
     * </pre>
     * Guaranteed resource of a/b are 30:70
     * Total cluster resource = 100
     * - A has 45 containers on two node, n1 has 10, n2 has 35, size of each
     * container is 1.
     * - B has 5 containers at n2, and reserves 1 container with size = 50 at n1,
     *   B also has 20 pending resources.
     *
     * Ideally B needs to preempt:
     * - 10 containers from n1 (for reserved)
     * - 5 containers from n2 for pending resources
     *
     * However, since one AM container is located at n1 (from queueA), we cannot
     * preempt 10 containers from n1 for reserved container. Instead, we will
     * preempt 15 containers from n2, since containers from queueA launched in n2
     * are later than containers from queueA launched in n1 (FIFO order of containers)
     */
    String labelsConfig = "=100,true;";
    // n1 / n2 has no label
    String // n1 / n2 has no label
    nodesConfig = "n1= res=50;" + "n2= res=50";
    String queuesConfig = // guaranteed,max,used,pending,reserved
    //root
    "root(=[100 100 100 70 10]);" + // a
    "-a(=[30 100 45 0]);" + // b
    "-b(=[70 100 55 70 50])";
    String appsConfig = //queueName\t(priority,resource,host,expression,#repeat,reserved)
    // app1 in a
    "a\t" + // 10 in n1
    "(1,1,n1,,10,false)" + // 35 in n2
    "(1,1,n2,,35,false);" + // app2 in b
    "b\t" + // 5 in n2
    "(1,1,n2,,5,false)" + // 1 container with size=50 reserved at n1
    "(1,50,n1,,1,true)";
    buildEnv(labelsConfig, nodesConfig, queuesConfig, appsConfig);
    policy.editSchedule();
    verify(mDisp, times(15)).handle(argThat(new TestProportionalCapacityPreemptionPolicy.IsPreemptionRequestFor(getAppAttemptId(1))));
    verify(mDisp, times(0)).handle(argThat(new IsPreemptionRequestForQueueAndNode(getAppAttemptId(1), "a", NodeId.newInstance("n1", 1))));
    verify(mDisp, times(15)).handle(argThat(new IsPreemptionRequestForQueueAndNode(getAppAttemptId(1), "a", NodeId.newInstance("n2", 1))));
    verify(mDisp, times(0)).handle(argThat(new TestProportionalCapacityPreemptionPolicy.IsPreemptionRequestFor(getAppAttemptId(2))));
}

