@Test
public void testAMBlackListConfigFromApp() {
    // Scenario 1: Application enables AM blacklisting
    float disableThreshold = 0.9f;
    conf.setBoolean(YarnConfiguration.AM_BLACKLISTING_ENABLED, false);
    ApplicationSubmissionContext submissionContext = new ApplicationSubmissionContextPBImpl();
    submissionContext.setAMBlackListRequest(AMBlackListingRequest.newInstance(true, disableThreshold));
    RMAppImpl application = (RMAppImpl) createNewTestApp(submissionContext);
    Assert.assertTrue(application.isAmBlacklistingEnabled());
    Assert.assertEquals(disableThreshold, application.getAmBlacklistingDisableThreshold(), 1e-8);
    // Scenario 2: Application disables AM blacklisting
    float globalThreshold = 0.9f;
    conf.setBoolean(YarnConfiguration.AM_BLACKLISTING_ENABLED, true);
    conf.setFloat(YarnConfiguration.AM_BLACKLISTING_DISABLE_THRESHOLD, globalThreshold);
    ApplicationSubmissionContext submissionContext2 = new ApplicationSubmissionContextPBImpl();
    submissionContext2.setAMBlackListRequest(AMBlackListingRequest.newInstance(false, disableThreshold));
    RMAppImpl application2 = (RMAppImpl) createNewTestApp(submissionContext2);
    // Am blacklisting will be disabled eventhough its enabled in RM.
    Assert.assertFalse(application2.isAmBlacklistingEnabled());
    // Scenario 3: Application updates invalid AM threshold
    float invalidDisableThreshold = -0.5f;
    conf.setBoolean(YarnConfiguration.AM_BLACKLISTING_ENABLED, true);
    conf.setFloat(YarnConfiguration.AM_BLACKLISTING_DISABLE_THRESHOLD, globalThreshold);
    ApplicationSubmissionContext submissionContext3 = new ApplicationSubmissionContextPBImpl();
    submissionContext3.setAMBlackListRequest(AMBlackListingRequest.newInstance(true, invalidDisableThreshold));
    RMAppImpl application3 = (RMAppImpl) createNewTestApp(submissionContext3);
    Assert.assertTrue(application3.isAmBlacklistingEnabled());
    Assert.assertEquals(globalThreshold, application3.getAmBlacklistingDisableThreshold(), 1e-8);
    // Scenario 4: Empty AMBlackListingRequest in Submission Context
    conf.setBoolean(YarnConfiguration.AM_BLACKLISTING_ENABLED, true);
    conf.setFloat(YarnConfiguration.AM_BLACKLISTING_DISABLE_THRESHOLD, globalThreshold);
    ApplicationSubmissionContext submissionContext4 = new ApplicationSubmissionContextPBImpl();
    RMAppImpl application4 = (RMAppImpl) createNewTestApp(submissionContext4);
    Assert.assertTrue(application4.isAmBlacklistingEnabled());
    Assert.assertEquals(globalThreshold, application4.getAmBlacklistingDisableThreshold(), 1e-8);
}

@Test
public void testReleaseWhileRunning() {
    DrainDispatcher drainDispatcher = new DrainDispatcher();
    EventHandler<RMAppAttemptEvent> appAttemptEventHandler = mock(EventHandler.class);
    EventHandler generic = mock(EventHandler.class);
    drainDispatcher.register(RMAppAttemptEventType.class, appAttemptEventHandler);
    drainDispatcher.register(RMNodeEventType.class, generic);
    drainDispatcher.init(new YarnConfiguration());
    drainDispatcher.start();
    NodeId nodeId = BuilderUtils.newNodeId("host", 3425);
    ApplicationId appId = BuilderUtils.newApplicationId(1, 1);
    ApplicationAttemptId appAttemptId = BuilderUtils.newApplicationAttemptId(appId, 1);
    ContainerId containerId = BuilderUtils.newContainerId(appAttemptId, 1);
    ContainerAllocationExpirer expirer = mock(ContainerAllocationExpirer.class);
    Resource resource = BuilderUtils.newResource(512, 1);
    Priority priority = BuilderUtils.newPriority(5);
    Container container = BuilderUtils.newContainer(containerId, nodeId, "host:3465", resource, priority, null);
    ConcurrentMap<ApplicationId, RMApp> rmApps = spy(new ConcurrentHashMap<ApplicationId, RMApp>());
    RMApp rmApp = mock(RMApp.class);
    when(rmApp.getRMAppAttempt((ApplicationAttemptId) Matchers.any())).thenReturn(null);
    Mockito.doReturn(rmApp).when(rmApps).get((ApplicationId) Matchers.any());
    RMApplicationHistoryWriter writer = mock(RMApplicationHistoryWriter.class);
    SystemMetricsPublisher publisher = mock(SystemMetricsPublisher.class);
    RMContext rmContext = mock(RMContext.class);
    when(rmContext.getDispatcher()).thenReturn(drainDispatcher);
    when(rmContext.getContainerAllocationExpirer()).thenReturn(expirer);
    when(rmContext.getRMApplicationHistoryWriter()).thenReturn(writer);
    when(rmContext.getRMApps()).thenReturn(rmApps);
    when(rmContext.getSystemMetricsPublisher()).thenReturn(publisher);
    YarnConfiguration conf = new YarnConfiguration();
    conf.setBoolean(YarnConfiguration.APPLICATION_HISTORY_SAVE_NON_AM_CONTAINER_META_INFO, true);
    when(rmContext.getYarnConfiguration()).thenReturn(conf);
    RMContainer rmContainer = new RMContainerImpl(container, appAttemptId, nodeId, "user", rmContext);
    assertEquals(RMContainerState.NEW, rmContainer.getState());
    assertEquals(resource, rmContainer.getAllocatedResource());
    assertEquals(nodeId, rmContainer.getAllocatedNode());
    assertEquals(priority, rmContainer.getAllocatedPriority());
    verify(writer).containerStarted(any(RMContainer.class));
    verify(publisher).containerCreated(any(RMContainer.class), anyLong());
    rmContainer.handle(new RMContainerEvent(containerId, RMContainerEventType.START));
    drainDispatcher.await();
    assertEquals(RMContainerState.ALLOCATED, rmContainer.getState());
    rmContainer.handle(new RMContainerEvent(containerId, RMContainerEventType.ACQUIRED));
    drainDispatcher.await();
    assertEquals(RMContainerState.ACQUIRED, rmContainer.getState());
    rmContainer.handle(new RMContainerEvent(containerId, RMContainerEventType.LAUNCHED));
    drainDispatcher.await();
    assertEquals(RMContainerState.RUNNING, rmContainer.getState());
    assertEquals("http://host:3465/node/containerlogs/container_1_0001_01_000001/user", rmContainer.getLogURL());
    // In RUNNING state. Verify RELEASED and associated actions.
    reset(appAttemptEventHandler);
    ContainerStatus containerStatus = SchedulerUtils.createAbnormalContainerStatus(containerId, SchedulerUtils.RELEASED_CONTAINER);
    rmContainer.handle(new RMContainerFinishedEvent(containerId, containerStatus, RMContainerEventType.RELEASED));
    drainDispatcher.await();
    assertEquals(RMContainerState.RELEASED, rmContainer.getState());
    assertEquals(SchedulerUtils.RELEASED_CONTAINER, rmContainer.getDiagnosticsInfo());
    assertEquals(ContainerExitStatus.ABORTED, rmContainer.getContainerExitStatus());
    assertEquals(ContainerState.COMPLETE, rmContainer.getContainerState());
    verify(writer).containerFinished(any(RMContainer.class));
    verify(publisher).containerFinished(any(RMContainer.class), anyLong());
    ArgumentCaptor<RMAppAttemptContainerFinishedEvent> captor = ArgumentCaptor.forClass(RMAppAttemptContainerFinishedEvent.class);
    verify(appAttemptEventHandler).handle(captor.capture());
    RMAppAttemptContainerFinishedEvent cfEvent = captor.getValue();
    assertEquals(appAttemptId, cfEvent.getApplicationAttemptId());
    assertEquals(containerStatus, cfEvent.getContainerStatus());
    assertEquals(RMAppAttemptEventType.CONTAINER_FINISHED, cfEvent.getType());
    // In RELEASED state. A FINIHSED event may come in.
    rmContainer.handle(new RMContainerFinishedEvent(containerId, SchedulerUtils.createAbnormalContainerStatus(containerId, "FinishedContainer"), RMContainerEventType.FINISHED));
    assertEquals(RMContainerState.RELEASED, rmContainer.getState());
}

